/* ------------------------------------------------------------------ */
/* splat + glow helpers                                                */
/* ------------------------------------------------------------------ */
export function makeSplatTexture() {
  const s = 128;
  const c = makeCanvas(s, s);
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, s, s);
  ctx.translate(s / 2, s / 2);
  const blob = (x, y, r, a) => {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(255,255,255,${a})`);
    g.addColorStop(0.65, `rgba(255,255,255,${a * 0.7})`);
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
  };
  blob(0, 0, 34, 0.95);
  for (let i = 0; i < 18; i++) {
    const a = rand(0, TAU);
    const d = rand(18, 58);
    blob(Math.cos(a) * d, Math.sin(a) * d, rand(2, 8), rand(0.45, 0.9));
  }
  const tex = new THREE.CanvasTexture(c);
  return tex;
}

export function makeGlowTexture() {
  const s = 128;
  const c = makeCanvas(s, s);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.18, 'rgba(255,240,200,0.8)');
  g.addColorStop(0.5, 'rgba(255,180,90,0.24)');
  g.addColorStop(1, 'rgba(255,150,60,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  const tex = new THREE.CanvasTexture(c);
  return tex;
}

/* leaf geometry */
function makeLeafGeometry() {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.bezierCurveTo(0.12, 0.05, 0.24, 0.16, 0.28, 0.34);
  shape.bezierCurveTo(0.22, 0.3, 0.12, 0.24, 0, 0.12);
  shape.bezierCurveTo(-0.12, 0.24, -0.22, 0.3, -0.28, 0.34);
  shape.bezierCurveTo(-0.24, 0.16, -0.12, 0.05, 0, 0);
  const geo = new THREE.ShapeGeometry(shape, 8);
  geo.rotateX(-Math.PI / 2);
  return geo;
}

/* ------------------------------------------------------------------ */
/* factory                                                             */
/* ------------------------------------------------------------------ */
export class FruitFactory {
  constructor() {
    this.rindTextures = {};
    this.fleshTextures = {};
    this.materials = {};
    this.bumpTexture = null;
    this.geometries = new Map();
    this.halfGeometries = new Map();
    this.halfMaterials = {};
    this.splatTexture = makeSplatTexture();
    this.glowTexture = makeGlowTexture();
    this.leafGeometry = makeLeafGeometry();
    this.stemGeometry = new THREE.CylinderGeometry(0.026, 0.04, 0.2, 6, 1);
    this.leafMaterial = new THREE.MeshStandardMaterial({
      color: 0x4a9638, roughness: 0.65, metalness: 0,
      side: THREE.DoubleSide, emissive: 0x0d2b08, emissiveIntensity: 0.5,
    });
    this.stemMaterial = new THREE.MeshStandardMaterial({ color: 0x51301a, roughness: 0.9 });
    this.bombBodyMaterial = new THREE.MeshStandardMaterial({
      color: 0x131018, roughness: 0.32, metalness: 0.72,
      emissive: 0x2a0508, emissiveIntensity: 0.6,
    });
    this.bombBandMaterial = new THREE.MeshStandardMaterial({
      color: 0xff3344, roughness: 0.35, metalness: 0.2,
      emissive: 0xff2030, emissiveIntensity: 2.2,
    });
    this.bombFuseMaterial = new THREE.MeshStandardMaterial({ color: 0x5c452e, roughness: 0.95 });
    this.bombSparkMaterial = new THREE.SpriteMaterial({
      map: this.glowTexture, color: 0xffc36a, blending: THREE.AdditiveBlending,
      transparent: true, depthWrite: false, opacity: 0.95,
    });
    this.goldGlowMaterial = new THREE.SpriteMaterial({
      map: this.glowTexture, color: 0xffc860, blending: THREE.AdditiveBlending,
      transparent: true, depthWrite: false, opacity: 0.55,
    });

    this._buildBump();

    // Pre-generate everything so first spawn never hitches.
    for (const id of Object.keys(FRUIT_DEFS)) {
      this._prepare(id);
    }
  }

  _buildBump() {
    const w = 256; const h = 128;
    const c = makeCanvas(w, h);
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#808080';
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 18000; i++) {
      ctx.fillStyle = `rgba(${Math.random() > 0.5 ? 255 : 0},${Math.random() > 0.5 ? 255 : 0},255,0.05)`;
      ctx.fillRect(rand(0, w), rand(0, h), rand(0.5, 2), rand(0.5, 2));
    }
    const tex = toTexture(c, { srgb: false });
    this.bumpTexture = tex;
  }

  _prepare(id) {
    if (this.rindTextures[id]) return;
    const def = FRUIT_DEFS[id];
    const c = makeCanvas(512, 256);
    RIND_PAINTERS[id](c.getContext('2d'), 512, 256);
    this.rindTextures[id] = toTexture(c);

    const fc = fleshCanvas(def);
    this.fleshTextures[id] = toTexture(fc);

    const isGolden = id === 'golden';
    const material = new THREE.MeshStandardMaterial({
      map: this.rindTextures[id],
      bumpMap: this.bumpTexture,
      bumpScale: 0.012,
      roughness: isGolden ? 0.26 : 0.46,
      metalness: isGolden ? 0.5 : 0.02,
      emissive: isGolden ? 0xffb347 : 0x000000,
      emissiveIntensity: isGolden ? 0.32 : 0,
      envMapIntensity: 0.45,
    });
    this.materials[id] = material;

    const fleshMaterial = new THREE.MeshStandardMaterial({
      map: this.fleshTextures[id],
      roughness: 0.52,
      metalness: 0,
      emissive: isGolden ? 0x6b3f00 : 0x000000,
      emissiveIntensity: isGolden ? 0.25 : 0,
      side: THREE.DoubleSide,
    });
    const rimMaterial = new THREE.MeshStandardMaterial({
      color: def.rim, roughness: 0.55, metalness: 0.01,
      side: THREE.DoubleSide, emissive: isGolden ? 0x8a5a10 : 0x000000,
      emissiveIntensity: isGolden ? 0.4 : 0,
    });
    this.halfMaterials[id] = { flesh: fleshMaterial, rim: rimMaterial };
  }

  _sphereGeo(radius) {
    const key = radius.toFixed(3);
    let geo = this.geometries.get(key);
    if (!geo) {
      geo = new THREE.SphereGeometry(radius, 28, 20);
      this.geometries.set(key, geo);
    }
    return geo;
  }

  _halfGeos(radius) {
    const key = radius.toFixed(3);
    let pack = this.halfGeometries.get(key);
    if (!pack) {
      pack = {
        dome: new THREE.SphereGeometry(radius, 30, 18, Math.PI, Math.PI),
        cap: new THREE.CircleGeometry(radius * 0.975, 40),
        rim: new THREE.TorusGeometry(radius * 0.975, radius * 0.028, 8, 44),
      };
      this.halfGeometries.set(key, pack);
    }
    return pack;
  }

  createFruit(typeId, scale = 1) {
    const def = FRUIT_DEFS[typeId];
    this._prepare(typeId);
    const group = new THREE.Group();
    const radius = def.radius * scale * rand(0.94, 1.06);

    const mesh = new THREE.Mesh(this._sphereGeo(radius), this.materials[typeId]);
    mesh.scale.set(def.shape[0], def.shape[1], def.shape[2]);
    group.add(mesh);

    if (def.leaf) {
      const stem = new THREE.Mesh(this.stemGeometry, this.stemMaterial);
      stem.position.set(radius * 0.1, radius * def.shape[1] * 0.97, 0);
      stem.rotation.z = -0.28;
      stem.scale.setScalar(radius * 1.3);
      group.add(stem);

      const leaf = new THREE.Mesh(this.leafGeometry, this.leafMaterial);
      leaf.position.set(radius * 0.24, radius * def.shape[1] * 1.0, 0);
      leaf.rotation.set(rand(-0.3, 0.3), rand(-0.5, 0.5), rand(-0.5, -0.1));
      leaf.scale.setScalar(radius * 0.95);
      group.add(leaf);
    } else if (def.id === 'dragon') {
      const stem = new THREE.Mesh(this.stemGeometry, this.stemMaterial);
      stem.position.set(0, radius * 1.02, 0);
      stem.scale.setScalar(radius * 1.1);
      group.add(stem);
    }

    if (def.special) {
      const glow = new THREE.Sprite(this.goldGlowMaterial.clone());
      glow.scale.setScalar(radius * 5.6);
      glow.material.opacity = 0.5;
      group.add(glow);
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(radius * 1.5, radius * 0.018, 6, 60),
        new THREE.MeshBasicMaterial({ color: 0xffd27a, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false }),
      );
      ring.rotation.x = rand(0.3, 0.9);
      ring.rotation.y = rand(0.3, 0.9);
      group.add(ring);
      group.userData.ring = ring;
      group.userData.glow = glow;
    }

    group.userData.radius = radius;
    group.userData.def = def;
    group.userData.spin = new THREE.Vector3(rand(-1, 1), rand(-1, 1), rand(-1, 1)).normalize();
    group.userData.spinSpeed = rand(0.5, 1.4);
    return { group, radius, def };
  }

  createBomb(scale = 1) {
    const group = new THREE.Group();
    const radius = 0.82 * scale;

    const body = new THREE.Mesh(new THREE.SphereGeometry(radius, 26, 20), this.bombBodyMaterial);
    group.add(body);

    const band = new THREE.Mesh(
      new THREE.TorusGeometry(radius * 0.99, radius * 0.07, 8, 44),
      this.bombBandMaterial,
    );
    band.rotation.x = Math.PI / 2;
    group.add(band);

    const band2 = band.clone();
    band2.rotation.set(0.5, 0.3, Math.PI / 2);
    band2.scale.setScalar(0.92);
    group.add(band2);

    const fuse = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.05, 0.28, 6), this.bombFuseMaterial);
    fuse.position.set(radius * 0.26, radius + 0.12, 0);
    fuse.rotation.z = -0.5;
    group.add(fuse);

    const spark = new THREE.Sprite(this.bombSparkMaterial.clone());
    spark.position.set(radius * 0.42, radius + 0.22, 0);
    spark.scale.setScalar(0.7);
    group.add(spark);
    group.userData.spark = spark;

    const glow = new THREE.Sprite(this.goldGlowMaterial.clone());
    glow.material.color.setHex(0xff3322);
    glow.position.copy(spark.position);
    glow.scale.setScalar(1.9);
    glow.material.opacity = 0.5;
    group.add(glow);
    group.userData.glow = glow;

    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(radius * 1.25, 0.012, 5, 48),
      new THREE.MeshBasicMaterial({ color: 0xff4d5e, transparent: true, opacity: 0.45, blending: THREE.AdditiveBlending, depthWrite: false }),
    );
    ring.rotation.x = Math.PI / 2.4;
    group.add(ring);
    group.userData.ring = ring;

    group.userData.radius = radius;
    group.userData.spin = new THREE.Vector3(rand(-0.6, 0.6), rand(-0.6, 0.6), 0);
    group.userData.spinSpeed = 0.8;
    group.userData.isBomb = true;
    return { group, radius, def: null };
  }

  createHalves(typeId, radius, cutAngle) {
    this._prepare(typeId);
    const pack = this._halfGeos(Number(radius.toFixed(3)));
    const mats = this.halfMaterials[typeId];
    const halves = [];
    for (let i = 0; i < 2; i++) {
      const g = new THREE.Group();
      const dome = new THREE.Mesh(pack.dome, this.materials[typeId]);
      dome.scale.copy(new THREE.Vector3(...FRUIT_DEFS[typeId].shape));
      g.add(dome);

      const cap = new THREE.Mesh(pack.cap, mats.flesh);
      cap.position.z = 0.004;
      g.add(cap);

      const rim = new THREE.Mesh(pack.rim, mats.rim);
      rim.position.z = 0.002;
      g.add(rim);

      // Tilt the cut face toward the camera to show the juicy cross-section.
      const side = i === 0 ? 1 : -1;
      g.rotation.x = rand(-0.35, 0.35);
      g.rotation.y = side * rand(0.2, 0.65);
      g.rotation.z = rand(-0.2, 0.2);
      g.scale.setScalar(rand(0.97, 1.03));

      const normal = new THREE.Vector3(-Math.sin(cutAngle), Math.cos(cutAngle), 0);
      const dir = i === 0 ? 1 : -1;
      halves.push({
        group: g,
        velocity: new THREE.Vector3(normal.x * dir * rand(1.6, 3.4), normal.y * dir * rand(1.6, 3.4) + 1.8, 0),
        spin: new THREE.Vector3(rand(-3, 3), rand(-3, 3), rand(-4, 4)),
        age: 0,
        side,
      });
    }
    return halves;
  }
}

import * as THREE from 'three';
import { makeGlowTexture, makeSplatTexture } from './fruits.js';

const TAU = Math.PI * 2;
const tmpColor = new THREE.Color();

/* ------------------------------------------------------------------ */
/* soft round particles                                               */
/* ------------------------------------------------------------------ */
class ParticlePool {
  constructor(scene, { max = 400, blending = THREE.NormalBlending, glow = false } = {}) {
    this.max = max;
    this.items = [];
    this.cursor = 0;
    this.glow = glow;

    this.geometry = new THREE.BufferGeometry();
    this.positions = new Float32Array(max * 3);
    this.colors = new Float32Array(max * 3);
    this.sizes = new Float32Array(max);
    this.alphas = new Float32Array(max);
    this.geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    this.geometry.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
    this.geometry.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
    this.geometry.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));

    this.material = new THREE.ShaderMaterial({
      uniforms: { uScale: { value: 900 } },
      vertexShader: `
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        uniform float uScale;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = aColor;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_Position = projectionMatrix * mv;
          gl_PointSize = clamp(aSize * uScale / max(1.0, -mv.z), 1.0, 80.0);
        }
      `,
      fragmentShader: `
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec2 c = gl_PointCoord - 0.5;
          float d = length(c);
          if (d > 0.5) discard;
          float a = smoothstep(0.5, 0.08, d);
          vec3 col = vColor;
          // juicy highlight
          float hi = smoothstep(0.34, 0.05, length(c - vec2(-0.14, 0.15)));
          col += hi * 0.35;
          gl_FragColor = vec4(col, a * vAlpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      depthTest: true,
      blending,
    });

    this.points = new THREE.Points(this.geometry, this.material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 20;
    scene.add(this.points);
  }

  setScale(scale) { this.material.uniforms.uScale.value = scale; }

  spawn({ position, velocity, color, size, life, gravity = 4, drag = 0.15, alpha = 1 }) {
    const item = {
      px: position.x, py: position.y, pz: position.z,
      vx: velocity.x, vy: velocity.y, vz: velocity.z,
      color: new THREE.Color(color),
      size, life, maxLife: life, gravity, drag, alpha: alpha,
    };
    if (this.items.length < this.max) {
      this.items.push(item);
    } else {
      this.items[this.cursor % this.max] = item;
      this.cursor++;
    }
  }

  update(dt) {
    const items = this.items;
    for (let i = items.length - 1; i >= 0; i--) {
      const it = items[i];
      it.life -= dt;
      if (it.life <= 0) {
        items.splice(i, 1);
        continue;
      }
      it.vy -= it.gravity * dt;
      const dragFactor = Math.exp(-it.drag * dt * 8);
      it.vx *= dragFactor;
      it.vy *= dragFactor;
      it.vz *= dragFactor;
      it.px += it.vx * dt;
      it.py += it.vy * dt;
      it.pz += it.vz * dt;
    }

    const n = Math.min(items.length, this.max);
    for (let i = 0; i < this.max; i++) {
      const it = items[i];
      if (!it) {
        this.alphas[i] = 0;
        this.sizes[i] = 0;
        this.positions[i * 3] = 0;
        this.positions[i * 3 + 1] = -999;
        this.positions[i * 3 + 2] = 0;
        continue;
      }
      const t = it.life / it.maxLife;
      this.positions[i * 3] = it.px;
      this.positions[i * 3 + 1] = it.py;
      this.positions[i * 3 + 2] = it.pz;
      this.colors[i * 3] = it.color.r;
      this.colors[i * 3 + 1] = it.color.g;
      this.colors[i * 3 + 2] = it.color.b;
      this.sizes[i] = it.size * (0.55 + t * 0.65);
      this.alphas[i] = it.alpha * Math.min(1, t * 2.4);
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
    this.geometry.setDrawRange(0, this.max);
  }
}

/* ------------------------------------------------------------------ */
/* ribbon trail                                                        */
/* ------------------------------------------------------------------ */
class Trail {
  constructor(scene, glowTexture) {
    this.points = [];
    this.maxAge = 0.34;
    this.time = 0;
    this.color = new THREE.Color(0x8beaff);
    this.width = 1;
    this.maxPoints = 64;

    const makeRibbon = (opacity, widthFactor, bright) => {
      const geo = new THREE.BufferGeometry();
      const positions = new Float32Array(this.maxPoints * 2 * 3);
      const alphas = new Float32Array(this.maxPoints * 2);
      const uvs = new Float32Array(this.maxPoints * 2 * 2);
      geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      geo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));
      geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
      const idx = [];
      for (let i = 0; i < this.maxPoints - 1; i++) {
        idx.push(i * 2, i * 2 + 1, i * 2 + 2, i * 2 + 1, i * 2 + 3, i * 2 + 2);
      }
      geo.setIndex(idx);
      geo.setDrawRange(0, 0);
      const mat = new THREE.ShaderMaterial({
        uniforms: {
          uColor: { value: new THREE.Color(0xffffff) },
          uOpacity: { value: opacity },
          uBright: { value: bright },
        },
        vertexShader: `
          attribute float aAlpha;
          varying float vAlpha;
          varying vec2 vUv;
          void main() {
            vAlpha = aAlpha;
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          }
        `,
        fragmentShader: `
          uniform vec3 uColor;
          uniform float uOpacity;
          uniform float uBright;
          varying float vAlpha;
          varying vec2 vUv;
          void main() {
            float edge = smoothstep(0.0, 0.42, vUv.x) * smoothstep(1.0, 0.58, vUv.x);
            float a = vAlpha * edge * uOpacity;
            if (a < 0.002) discard;
            gl_FragColor = vec4(uColor * uBright, a);
          }
        `,
        transparent: true,
        depthWrite: false,
        depthTest: false,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.frustumCulled = false;
      mesh.renderOrder = 50;
      scene.add(mesh);
      return { mesh, geo, positions, alphas, uvs, mat, widthFactor };
    };

    this.outer = makeRibbon(0.55, 1, 1.15);
    this.core = makeRibbon(0.95, 0.38, 1.9);

    this.glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture, color: 0x8beaff, transparent: true,
      blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
    }));
    this.glow.scale.setScalar(1.2);
    this.glow.renderOrder = 51;
    scene.add(this.glow);
    this.lastPointAt = -10;
  }

  setColor(color) {
    const c = new THREE.Color(color);
    this.color.copy(c);
    this.outer.mat.uniforms.uColor.value.copy(c);
    this.core.mat.uniforms.uColor.value.copy(c).lerp(new THREE.Color(0xffffff), 0.65);
    this.glow.material.color.copy(c);
  }

  push(point, time) {
    const pts = this.points;
    const last = pts[pts.length - 1];
    if (last && Math.hypot(point.x - last.x, point.y - last.y) < 0.008) {
      last.t = time;
      this.lastPointAt = time;
      return;
    }
    pts.push({ x: point.x, y: point.y, z: point.z ?? 1.4, t: time });
    if (pts.length > this.maxPoints) pts.shift();
    this.lastPointAt = time;
  }

  clear() { this.points.length = 0; }

  update(time) {
    this.time = time;
    const pts = this.points;
    while (pts.length && time - pts[0].t > this.maxAge) pts.shift();

    if (pts.length < 2) {
      this.outer.geo.setDrawRange(0, 0);
      this.core.geo.setDrawRange(0, 0);
      this.glow.material.opacity = 0;
      return;
    }

    const n = pts.length;
    const head = pts[n - 1];
    for (const ribbon of [this.outer, this.core]) {
      const { positions, alphas, uvs, geo } = ribbon;
      const widthBase = 0.2 * this.width * ribbon.widthFactor;
      for (let i = 0; i < n; i++) {
        const p = pts[i];
        const prev = pts[Math.max(0, i - 1)];
        const next = pts[Math.min(n - 1, i + 1)];
        let dx = next.x - prev.x;
        let dy = next.y - prev.y;
        let len = Math.hypot(dx, dy);
        if (len < 0.0001) { dx = 1; dy = 0; len = 1; }
        const nx = -dy / len;
        const ny = dx / len;
        const age = (time - p.t) / this.maxAge;
        const u = n === 1 ? 1 : i / (n - 1);
        const taper = 0.18 + 0.82 * Math.pow(Math.sin(Math.PI * Math.min(1, u * 1.08)), 0.55);
        const width = widthBase * taper * (1 - age * 0.35) * this.width;
        const a = Math.pow(Math.max(0, 1 - age), 1.25);

        const i0 = i * 2;
        positions[i0 * 3] = p.x + nx * width;
        positions[i0 * 3 + 1] = p.y + ny * width;
        positions[i0 * 3 + 2] = p.z;
        positions[i0 * 3 + 3] = p.x - nx * width;
        positions[i0 * 3 + 4] = p.y - ny * width;
        positions[i0 * 3 + 5] = p.z;
        alphas[i0] = a;
        alphas[i0 + 1] = a;
        uvs[i0 * 2] = 0; uvs[i0 * 2 + 1] = 0;
        uvs[i0 * 2 + 2] = 1; uvs[i0 * 2 + 3] = 0;
      }
      geo.attributes.position.needsUpdate = true;
      geo.attributes.aAlpha.needsUpdate = true;
      geo.attributes.uv.needsUpdate = true;
      geo.setDrawRange(0, (n - 1) * 6);
    }

    this.glow.position.set(head.x, head.y, head.z + 0.05);
    const glowAge = (time - head.t) / this.maxAge;
    this.glow.material.opacity = Math.max(0, 1 - glowAge) * 0.75;
    this.glow.scale.setScalar((0.9 + Math.sin(time * 18) * 0.08) * this.width);
  }
}

/* ------------------------------------------------------------------ */
/* Effects                                                             */
/* ------------------------------------------------------------------ */
export class Effects {
  constructor(scene, camera, factory) {
    this.scene = scene;
    this.camera = camera;
    this.factory = factory;
    this.time = 0;
    this.shake = 0;
    this.flashCb = null;
    this.hurtCb = null;
    this.cameraBase = camera.position.clone();

    this.trail = new Trail(scene, factory.glowTexture);
    this.juice = new ParticlePool(scene, { max: 520, blending: THREE.NormalBlending });
    this.sparks = new ParticlePool(scene, { max: 420, blending: THREE.AdditiveBlending });

    this.splatTexture = factory.splatTexture;
    this.glowTexture = makeGlowTexture();
    this._initSplats();
    this._initSlashes();
    this._initShocks();
    this._initArcs();
    this._initPopups();
  }

  setViewport(heightPx, fovRad) {
    const scale = heightPx / (2 * Math.tan(fovRad / 2));
    this.juice.setScale(scale);
    this.sparks.setScale(scale);
  }

  setPixelRatio() { /* responsive point sizes handled by uScale */ }

  addShake(amount) { this.shake = Math.min(1.6, this.shake + amount); }

  /* ---------- splat decals ---------- */
  _initSplats() {
    this.splats = [];
    const geo = new THREE.PlaneGeometry(1, 1);
    for (let i = 0; i < 26; i++) {
      const mat = new THREE.MeshBasicMaterial({
        map: this.splatTexture, transparent: true, depthWrite: false,
        depthTest: true, opacity: 0, color: 0xffffff, side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.visible = false;
      mesh.position.z = -2;
      this.scene.add(mesh);
      this.splats.push({ mesh, age: 0, life: 1, active: false });
    }
  }

  addSplat(position, color, scale = 2.4) {
    let slot = this.splats.find((s) => !s.active) || this.splats[0];
    slot.active = true;
    slot.age = 0;
    slot.life = 5.2 + Math.random() * 3.2;
    slot.mesh.visible = true;
    slot.mesh.material.color.set(color);
    slot.mesh.material.opacity = 0;
    slot.mesh.position.set(
      position.x + (Math.random() - 0.5) * 1.4,
      position.y + (Math.random() - 0.5) * 1.4,
      -1.6 - Math.random() * 3.6,
    );
    slot.mesh.rotation.z = Math.random() * TAU;
    const s = scale * (0.8 + Math.random() * 0.7);
    slot.mesh.scale.set(s * 1.25, s, 1);
  }

  _updateSplats(dt) {
    for (const s of this.splats) {
      if (!s.active) continue;
      s.age += dt;
      const t = s.age / s.life;
      if (t >= 1) {
        s.active = false;
        s.mesh.visible = false;
        continue;
      }
      s.mesh.material.opacity = Math.min(1, t * 8) * (1 - t) * 0.62;
      s.mesh.scale.multiplyScalar(1 + dt * 0.035);
    }
  }

  /* ---------- slash streaks ---------- */
  _initSlashes() {
    const c = document.createElement('canvas');
    c.width = 256; c.height = 64;
    const ctx = c.getContext('2d');
    const g = ctx.createLinearGradient(0, 0, 256, 0);
    g.addColorStop(0, 'rgba(255,255,255,0)');
    g.addColorStop(0.18, 'rgba(255,255,255,0.6)');
    g.addColorStop(0.5, 'rgba(255,255,255,1)');
    g.addColorStop(0.82, 'rgba(255,255,255,0.6)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 22, 256, 20);
    const v = ctx.createLinearGradient(0, 0, 0, 64);
    v.addColorStop(0, 'rgba(255,255,255,0)');
    v.addColorStop(0.5, 'rgba(255,255,255,1)');
    v.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, 256, 64);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    this.slashTexture = tex;

    this.slashes = [];
    const geo = new THREE.PlaneGeometry(1, 1);
    for (let i = 0; i < 10; i++) {
      const mat = new THREE.MeshBasicMaterial({
        map: tex, transparent: true, depthWrite: false, depthTest: false,
        blending: THREE.AdditiveBlending, color: 0xffffff, opacity: 0,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.visible = false;
      mesh.renderOrder = 48;
      this.scene.add(mesh);
      this.slashes.push({ mesh, age: 0, life: 0.24, active: false });
    }
  }

  addSlash(position, angle, color, size = 1) {
    const slot = this.slashes.find((s) => !s.active) || this.slashes[0];
    slot.active = true;
    slot.age = 0;
    slot.life = 0.22;
    slot.mesh.visible = true;
    slot.mesh.material.color.set(color);
    slot.mesh.material.opacity = 0.95;
    slot.mesh.position.set(position.x, position.y, position.z + 0.6);
    slot.mesh.rotation.z = angle;
    slot.mesh.scale.set(4.4 * size, 0.55 * size, 1);
  }

  _updateSlashes(dt) {
    for (const s of this.slashes) {
      if (!s.active) continue;
      s.age += dt;
      const t = s.age / s.life;
      if (t >= 1) { s.active = false; s.mesh.visible = false; continue; }
      s.mesh.material.opacity = (1 - t) * 0.95;
      s.mesh.scale.y = 0.55 + t * 0.5;
    }
  }

  /* ---------- shockwaves ---------- */
  _initShocks() {
    this.shocks = [];
    const geo = new THREE.RingGeometry(0.86, 1, 64);
    for (let i = 0; i < 8; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xffffff, transparent: true, opacity: 0,
        blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
        side: THREE.DoubleSide,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.visible = false;
      mesh.renderOrder = 45;
      this.scene.add(mesh);
      this.shocks.push({ mesh, age: 0, life: 0.5, active: false, scale: 3 });
    }
  }

  addShock(position, color, scale = 4, life = 0.5) {
    const slot = this.shocks.find((s) => !s.active) || this.shocks[0];
    slot.active = true;
    slot.age = 0;
    slot.life = life;
    slot.scale = scale;
    slot.mesh.visible = true;
    slot.mesh.material.color.set(color);
    slot.mesh.position.set(position.x, position.y, (position.z ?? 0) + 0.3);
    slot.mesh.rotation.z = Math.random() * TAU;
    slot.mesh.scale.setScalar(0.4);
  }

  _updateShocks(dt) {
    for (const s of this.shocks) {
      if (!s.active) continue;
      s.age += dt;
      const t = s.age / s.life;
      if (t >= 1) { s.active = false; s.mesh.visible = false; continue; }
      const ease = 1 - Math.pow(1 - t, 2.4);
      s.mesh.scale.setScalar(0.4 + ease * s.scale);
      s.mesh.material.opacity = (1 - t) * 0.65;
    }
  }

  /* ---------- chain lightning ---------- */
  _initArcs() {
    this.arcs = [];
    for (let i = 0; i < 10; i++) {
      const geo = new THREE.BufferGeometry();
      const positions = new Float32Array(14 * 3);
      geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      const mat = new THREE.LineBasicMaterial({
        color: 0x8beaff, transparent: true, opacity: 0,
        blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
      });
      const line = new THREE.Line(geo, mat);
      line.visible = false;
      line.renderOrder = 49;
      line.frustumCulled = false;
      this.scene.add(line);
      this.arcs.push({ line, geo, mat, age: 0, life: 0.32, active: false });
    }
  }

  addArc(from, to, color) {
    const slot = this.arcs.find((a) => !a.active) || this.arcs[0];
    slot.active = true;
    slot.age = 0;
    slot.life = 0.3;
    slot.line.visible = true;
    slot.mat.color.set(color);
    slot.mat.opacity = 0.95;
    const arr = slot.geo.attributes.position.array;
    const steps = 14;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const len = Math.max(0.001, Math.hypot(dx, dy));
    const nx = -dy / len;
    const ny = dx / len;
    for (let i = 0; i < steps; i++) {
      const t = i / (steps - 1);
      const jitter = Math.sin(t * Math.PI) * (Math.random() - 0.5) * Math.min(1.6, len * 0.18);
      const bow = Math.sin(t * Math.PI) * Math.min(1.3, len * 0.12);
      arr[i * 3] = from.x + dx * t + nx * (jitter + bow);
      arr[i * 3 + 1] = from.y + dy * t + ny * (jitter + bow);
      arr[i * 3 + 2] = 1.5;
    }
    slot.geo.attributes.position.needsUpdate = true;
    slot.geo.setDrawRange(0, steps);
    for (let i = 0; i < 6; i++) {
      const t = Math.random();
      this.sparks.spawn({
        position: new THREE.Vector3(from.x + dx * t, from.y + dy * t, 1.5),
        velocity: new THREE.Vector3((Math.random() - 0.5) * 1.6, (Math.random() - 0.5) * 1.6, 0),
        color: new THREE.Color(color).lerp(new THREE.Color(0xffffff), 0.5),
        size: 0.1 + Math.random() * 0.1, life: 0.22 + Math.random() * 0.25,
        gravity: 0, drag: 0.2,
      });
    }
  }

  _updateArcs(dt) {
    for (const a of this.arcs) {
      if (!a.active) continue;
      a.age += dt;
      const t = a.age / a.life;
      if (t >= 1) { a.active = false; a.line.visible = false; continue; }
      a.mat.opacity = (1 - t) * 0.9;
    }
  }

  /* ---------- text popups ---------- */
  _initPopups() {
    this.popups = [];
  }

  _makePopupTexture(text, color, sub) {
    const w = 512; const h = 256;
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    const ctx = c.getContext('2d');
    ctx.clearRect(0, 0, w, h);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '800 104px "Trebuchet MS", "Segoe UI", sans-serif';
    if (sub) ctx.font = '800 88px "Trebuchet MS", "Segoe UI", sans-serif';
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.55)';
    ctx.shadowBlur = 18;
    ctx.shadowOffsetY = 6;
    ctx.lineWidth = 12;
    ctx.strokeStyle = 'rgba(24,10,4,0.4)';
    ctx.strokeText(text, w / 2, sub ? 92 : h / 2);
    ctx.restore();
    const grad = ctx.createLinearGradient(0, 30, 0, 190);
    grad.addColorStop(0, '#fffdf4');
    grad.addColorStop(0.45, color);
    grad.addColorStop(1, color);
    ctx.fillStyle = grad;
    ctx.fillText(text, w / 2, sub ? 92 : h / 2);
    if (sub) {
      ctx.font = '700 32px "Segoe UI", sans-serif';
      ctx.fillStyle = 'rgba(255,244,226,0.78)';
      ctx.fillText(sub, w / 2, 178);
    }
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = 4;
    return tex;
  }

  addPopup(position, text, { color = '#ffd583', sub = '', scale = 1.5, life = 1.1, rise = 2.6 } = {}) {
    let slot = this.popups.find((p) => !p.active);
    if (!slot) {
      if (this.popups.length >= 18) {
        slot = this.popups.shift();
        this.scene.remove(slot.sprite);
        slot.sprite.material.map.dispose();
        slot.sprite.material.dispose();
      } else {
        const mat = new THREE.SpriteMaterial({ transparent: true, depthWrite: false, depthTest: false });
        const sprite = new THREE.Sprite(mat);
        sprite.renderOrder = 52;
        slot = { sprite, active: false, age: 0, life: 1, baseScale: 1, rise: 2.5, startY: 0 };
        this.scene.add(sprite);
        this.popups.push(slot);
      }
    }
    slot.active = true;
    slot.age = 0;
    slot.life = life;
    slot.rise = rise;
    slot.startY = position.y;
    slot.sprite.visible = true;
    slot.sprite.position.set(position.x, position.y, 2.2);
    slot.sprite.material.map?.dispose();
    slot.sprite.material.map = this._makePopupTexture(text, color, sub);
    slot.sprite.material.opacity = 0;
    slot.baseScale = scale;
    slot.sprite.scale.set(2.6 * scale, 1.3 * scale, 1);
  }

  _updatePopups(dt) {
    for (const p of this.popups) {
      if (!p.active) continue;
      p.age += dt;
      const t = p.age / p.life;
      if (t >= 1) { p.active = false; p.sprite.visible = false; continue; }
      p.sprite.material.opacity = t < 0.12 ? t / 0.12 : (1 - Math.pow((t - 0.12) / 0.88, 1.6));
      p.sprite.position.y = p.startY + p.rise * (1 - Math.pow(1 - t, 2));
      const s = p.baseScale * (t < 0.16 ? 0.6 + (t / 0.16) * 0.5 : 1.1 - Math.min(0.1, (t - 0.16) * 0.15));
      p.sprite.scale.set(2.6 * s, 1.3 * s, 1);
    }
  }

  /* ---------- game bursts ---------- */
  burstFruit(position, def, radius, tierColor) {
    const flesh = new THREE.Color(def.flesh);
    const rim = new THREE.Color(def.rim);
    const count = 26;
    for (let i = 0; i < count; i++) {
      const a = Math.random() * TAU;
      const speed = 1.4 + Math.random() * 5.4;
      tmpColor.copy(Math.random() > 0.35 ? flesh : rim);
      tmpColor.offsetHSL(0, 0, (Math.random() - 0.5) * 0.12);
      this.juice.spawn({
        position: new THREE.Vector3(position.x, position.y, position.z + 0.2),
        velocity: new THREE.Vector3(Math.cos(a) * speed, Math.sin(a) * speed + 1.6, (Math.random() - 0.5) * 1.5),
        color: tmpColor.clone(),
        size: 0.13 + Math.random() * 0.2,
        life: 0.55 + Math.random() * 0.65,
        gravity: 7.5,
        drag: 0.1,
        alpha: 0.95,
      });
    }
    for (let i = 0; i < 14; i++) {
      const a = Math.random() * TAU;
      this.sparks.spawn({
        position: new THREE.Vector3(position.x, position.y, position.z + 0.3),
        velocity: new THREE.Vector3(Math.cos(a) * (2 + Math.random() * 4), Math.sin(a) * (2 + Math.random() * 4) + 1, 0),
        color: new THREE.Color(tierColor).lerp(new THREE.Color(0xffffff), 0.3),
        size: 0.07 + Math.random() * 0.1,
        life: 0.3 + Math.random() * 0.3,
        gravity: 3,
        drag: 0.15,
      });
    }
    this.addSplat(position, def.rim, 2 + radius);
    if (Math.random() > 0.45) {
      this.addSplat(
        new THREE.Vector3(position.x + (Math.random() - 0.5) * 3, position.y + (Math.random() - 0.5) * 3, 0),
        def.rim, 1.3 + Math.random() * 1.4,
      );
    }
    this.addShock(position, tierColor, 2.4 + radius, 0.4);
    if (def.special) {
      for (let i = 0; i < 34; i++) {
        const a = Math.random() * TAU;
        const speed = 3 + Math.random() * 7;
        this.sparks.spawn({
          position: new THREE.Vector3(position.x, position.y, position.z + 0.4),
          velocity: new THREE.Vector3(Math.cos(a) * speed, Math.sin(a) * speed, (Math.random() - 0.5) * 2),
          color: new THREE.Color(0xffd983).lerp(new THREE.Color(0xffffff), Math.random()),
          size: 0.08 + Math.random() * 0.16,
          life: 0.5 + Math.random() * 0.7,
          gravity: 1.4,
          drag: 0.1,
        });
      }
      this.addShock(position, 0xffd583, 9, 0.75);
    }
  }

  burstBomb(position) {
    for (let i = 0; i < 46; i++) {
      const a = Math.random() * TAU;
      const speed = 2 + Math.random() * 9;
      const hot = Math.random() > 0.55;
      this.sparks.spawn({
        position: new THREE.Vector3(position.x, position.y, position.z + 0.4),
        velocity: new THREE.Vector3(Math.cos(a) * speed, Math.sin(a) * speed + 2, (Math.random() - 0.5) * 3),
        color: hot ? new THREE.Color(0xffcf6c) : new THREE.Color(0xff4a2a),
        size: 0.12 + Math.random() * 0.26,
        life: 0.45 + Math.random() * 0.75,
        gravity: 5,
        drag: 0.05,
      });
    }
    for (let i = 0; i < 28; i++) {
      const a = Math.random() * TAU;
      this.juice.spawn({
        position: new THREE.Vector3(position.x, position.y, position.z + 0.3),
        velocity: new THREE.Vector3(Math.cos(a) * (1 + Math.random() * 4), Math.sin(a) * (1 + Math.random() * 4), 0),
        color: new THREE.Color(i % 3 === 0 ? 0x2a2228 : 0x120d16),
        size: 0.3 + Math.random() * 0.5,
        life: 0.8 + Math.random() * 0.8,
        gravity: -0.5,
        drag: 0.3,
        alpha: 0.55,
      });
    }
    this.addShock(position, 0xff8a4a, 14, 0.7);
    this.addShock(position, 0xff3b30, 8, 0.45);
    this.addShake(0.9);
    this.flash?.('bomb');
    this.hurtFlash?.();
  }

  flash(kind) {
    if (this.flashCb) this.flashCb(kind);
  }

  hurtFlash() {
    if (this.hurtCb) this.hurtCb();
  }

  update(dt, time) {
    this.time = time;
    this.trail.update(time);
    this.juice.update(dt);
    this.sparks.update(dt);
    this._updateSplats(dt);
    this._updateSlashes(dt);
    this._updateShocks(dt);
    this._updateArcs(dt);
    this._updatePopups(dt);
    this.shake *= Math.exp(-dt * 6.5);
    if (this.shake < 0.002) this.shake = 0;
  }
}

import * as THREE from 'three';

const TAU = Math.PI * 2;

function radialTexture() {
  const s = 128;
  const c = document.createElement('canvas');
  c.width = s; c.height = s;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.2, 'rgba(255,255,255,0.7)');
  g.addColorStop(0.55, 'rgba(255,255,255,0.16)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function bannerTexture() {
  const w = 128; const h = 320;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#2b0d18';
  ctx.fillRect(0, 0, w, h);
  const g = ctx.createLinearGradient(0, 0, w, 0);
  g.addColorStop(0, 'rgba(0,0,0,0.55)');
  g.addColorStop(0.5, 'rgba(255,80,80,0.08)');
  g.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = 'rgba(255,196,110,0.5)';
  ctx.lineWidth = 3;
  ctx.strokeRect(9, 9, w - 18, h - 18);
  ctx.strokeStyle = 'rgba(255,225,185,0.8)';
  ctx.lineWidth = 10;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(w / 2, 132, 34, Math.PI * 0.32, Math.PI * 1.9);
  ctx.stroke();
  ctx.lineWidth = 6;
  ctx.strokeStyle = 'rgba(255,225,185,0.45)';
  ctx.beginPath();
  ctx.moveTo(w / 2 + 8, 226);
  ctx.lineTo(w / 2 - 6, 264);
  ctx.stroke();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function mistTexture() {
  const w = 512; const h = 128;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 0, h);
  g.addColorStop(0, 'rgba(255,255,255,0)');
  g.addColorStop(0.55, 'rgba(255,255,255,0.55)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
  const gx = ctx.createLinearGradient(0, 0, w, 0);
  gx.addColorStop(0, 'rgba(0,0,0,0)');
  gx.addColorStop(0.2, 'rgba(0,0,0,1)');
  gx.addColorStop(0.8, 'rgba(0,0,0,1)');
  gx.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.globalCompositeOperation = 'destination-in';
  ctx.fillStyle = gx;
  ctx.fillRect(0, 0, w, h);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function petalGeometry() {
  const s = new THREE.Shape();
  s.moveTo(0, 0.13);
  s.bezierCurveTo(0.11, 0.1, 0.12, -0.02, 0, -0.14);
  s.bezierCurveTo(-0.12, -0.02, -0.11, 0.1, 0, 0.13);
  return new THREE.ShapeGeometry(s, 6);
}

export function createWorld(scene, factory) {
  const root = new THREE.Group();
  scene.add(root);
  const backdrop = new THREE.Group();
  root.add(backdrop);

  const glowTex = factory.glowTexture;
  const softTex = radialTexture();
  const mistTex = mistTexture();

  /* ---------------- sky ---------------- */
  const skyMat = new THREE.ShaderMaterial({
    depthWrite: false,
    fog: false,
    uniforms: {
      uTop: { value: new THREE.Color(0x060309) },
      uMid: { value: new THREE.Color(0x150a26) },
      uBottom: { value: new THREE.Color(0x401a34) },
      uGlow: { value: new THREE.Color(0xa4483d) },
    },
    vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `
      varying vec2 vUv;
      uniform vec3 uTop; uniform vec3 uMid; uniform vec3 uBottom; uniform vec3 uGlow;
      void main(){
        vec3 col = mix(uBottom, uMid, smoothstep(0.0, 0.58, vUv.y));
        col = mix(col, uTop, smoothstep(0.42, 1.0, vUv.y));
        vec2 p = (vUv - vec2(0.33, 0.68)) * vec2(1.15, 1.0);
        float halo = exp(-length(p) * 5.2);
        col += uGlow * halo * 0.55;
        float horizon = exp(-abs(vUv.y - 0.22) * 12.0);
        col += vec3(0.16, 0.06, 0.08) * horizon;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const sky = new THREE.Mesh(new THREE.PlaneGeometry(260, 150), skyMat);
  sky.position.set(0, 10, -72);
  sky.renderOrder = -20;
  backdrop.add(sky);

  /* ---------------- stars ---------------- */
  {
    const count = 190;
    const pos = new Float32Array(count * 3);
    const col = new Float32Array(count * 3);
    const c = new THREE.Color();
    for (let i = 0; i < count; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 150;
      pos[i * 3 + 1] = Math.random() * 42 - 6;
      pos[i * 3 + 2] = -62 + Math.random() * 18;
      c.setHSL(0.55 + Math.random() * 0.15, 0.35, 0.55 + Math.random() * 0.4);
      col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    const mat = new THREE.PointsMaterial({
      size: 0.16, vertexColors: true, transparent: true, opacity: 0.85,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true, map: glowTex,
    });
    const stars = new THREE.Points(geo, mat);
    backdrop.add(stars);
    root.userData.stars = stars;
  }

  /* ---------------- mountains ---------------- */
  const mountainShape = (peaks, baseY, topY) => {
    const shape = new THREE.Shape();
    shape.moveTo(-90, baseY);
    shape.lineTo(-90, topY * 0.2);
    let x = -90;
    for (const peak of peaks) {
      shape.lineTo(peak[0] - 7, topY * peak[2]);
      shape.lineTo(peak[0], topY * peak[1]);
      shape.lineTo(peak[0] + 9, topY * (peak[2] * 0.7 + 0.1));
      x = peak[0] + 9;
    }
    shape.lineTo(90, topY * 0.28);
    shape.lineTo(90, baseY);
    shape.closePath();
    return new THREE.ShapeGeometry(shape);
  };

  const farMountains = new THREE.Mesh(
    mountainShape([[-58, 0.32, 0.12], [-36, 0.5, 0.2], [-12, 0.28, 0.16], [16, 0.55, 0.24], [44, 0.35, 0.14], [66, 0.45, 0.2]], -34, 18),
    new THREE.MeshBasicMaterial({ color: 0x170c26, transparent: true, opacity: 0.85, depthWrite: false }),
  );
  farMountains.position.set(0, -2.5, -48);
  farMountains.renderOrder = -15;
  backdrop.add(farMountains);

  const nearMountains = new THREE.Mesh(
    mountainShape([[-70, 0.5, 0.2], [-44, 0.3, 0.12], [-20, 0.6, 0.24], [8, 0.34, 0.16], [34, 0.52, 0.2], [58, 0.3, 0.12], [78, 0.48, 0.22]], -30, 16),
    new THREE.MeshBasicMaterial({ color: 0x0e0718, transparent: true, opacity: 0.95, depthWrite: false }),
  );
  nearMountains.position.set(0, -3.6, -40);
  nearMountains.renderOrder = -14;
  backdrop.add(nearMountains);

  /* ---------------- moon ---------------- */
  const moon = new THREE.Mesh(
    new THREE.SphereGeometry(3.1, 40, 30),
    new THREE.MeshBasicMaterial({ color: 0xffe6b4, fog: false }),
  );
  moon.position.set(-6.2, 8.1, -46);
  backdrop.add(moon);

  const moonGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: softTex, color: 0xffc47a, transparent: true, opacity: 0.5,
    blending: THREE.AdditiveBlending, depthWrite: false, depthTest: true,
  }));
  moonGlow.position.copy(moon.position).add(new THREE.Vector3(0, 0, 0.5));
  moonGlow.scale.setScalar(24);
  backdrop.add(moonGlow);

  const moonGlow2 = new THREE.Sprite(new THREE.SpriteMaterial({
    map: softTex, color: 0x8a5bff, transparent: true, opacity: 0.14,
    blending: THREE.AdditiveBlending, depthWrite: false,
  }));
  moonGlow2.position.copy(moonGlow.position);
  moonGlow2.scale.setScalar(50);
  backdrop.add(moonGlow2);

  /* ---------------- clouds / haze ---------------- */
  const clouds = [];
  for (let i = 0; i < 6; i++) {
    const mat = new THREE.SpriteMaterial({
      map: softTex, color: i % 2 ? 0x9a5b8a : 0xff9a6a,
      transparent: true, opacity: 0.055 + Math.random() * 0.05,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const sprite = new THREE.Sprite(mat);
    sprite.position.set((Math.random() - 0.5) * 40, -2 + Math.random() * 10, -36 + Math.random() * 12);
    sprite.scale.set(26 + Math.random() * 24, 7 + Math.random() * 5, 1);
    backdrop.add(sprite);
    clouds.push({ sprite, baseX: sprite.position.x, speed: 0.05 + Math.random() * 0.08, phase: Math.random() * TAU });
  }

  /* ---------------- torii gate ---------------- */
  const gate = new THREE.Group();
  gate.position.set(0, -1.2, -18);
  backdrop.add(gate);

  const woodMat = new THREE.MeshStandardMaterial({
    color: 0x35131f, roughness: 0.72, metalness: 0.12,
    emissive: 0x0b0208, emissiveIntensity: 0.6,
  });
  const woodDark = new THREE.MeshStandardMaterial({
    color: 0x1d0a12, roughness: 0.85, metalness: 0.05,
  });
  const goldMat = new THREE.MeshStandardMaterial({
    color: 0x6b4a20, roughness: 0.4, metalness: 0.55,
    emissive: 0x2a1804, emissiveIntensity: 0.8,
  });

  const pillars = [];
  for (const side of [-1, 1]) {
    const pillar = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.62, 17.5, 10), woodMat);
    pillar.position.set(side * 6.6, 0.6, 0);
    gate.add(pillar);
    pillars.push(pillar);

    const base = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 1.05, 1.1, 8), woodDark);
    base.position.set(side * 6.6, -8.2, 0);
    gate.add(base);

    const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.62, 0.52, 0.5, 8), goldMat);
    cap.position.set(side * 6.6, 9.4, 0);
    gate.add(cap);
  }

  const topBeam = new THREE.Mesh(new THREE.BoxGeometry(17.4, 0.85, 1.2), woodMat);
  topBeam.position.set(0, 9.0, 0);
  gate.add(topBeam);
  const topCap = new THREE.Mesh(new THREE.BoxGeometry(18.6, 0.28, 1.5), goldMat);
  topCap.position.set(0, 9.52, 0);
  gate.add(topCap);
  for (const side of [-1, 1]) {
    const tip = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.42, 1.3), woodMat);
    tip.position.set(side * 9.5, 9.42, 0);
    tip.rotation.z = side * 0.16;
    gate.add(tip);
  }

  const secondBeam = new THREE.Mesh(new THREE.BoxGeometry(15.6, 0.56, 0.9), woodMat);
  secondBeam.position.set(0, 7.35, 0);
  gate.add(secondBeam);

  const plaque = new THREE.Mesh(new THREE.BoxGeometry(2.2, 1.7, 0.28), woodDark);
  plaque.position.set(0, 8.15, 0.2);
  gate.add(plaque);
  const plaqueTrim = new THREE.Mesh(new THREE.BoxGeometry(2.5, 0.12, 0.32), goldMat);
  plaqueTrim.position.set(0, 8.95, 0.2);
  gate.add(plaqueTrim);
  const plaqueTrim2 = plaqueTrim.clone();
  plaqueTrim2.position.y = 7.35;
  gate.add(plaqueTrim2);

  // hanging banners
  const bannerTex = bannerTexture();
  for (const side of [-1, 1]) {
    const banner = new THREE.Mesh(
      new THREE.PlaneGeometry(1.9, 4.6),
      new THREE.MeshStandardMaterial({
        map: bannerTex, roughness: 0.9, side: THREE.DoubleSide,
        emissive: 0x240810, emissiveIntensity: 0.5,
      }),
    );
    banner.position.set(side * 3.9, 3.0, 0.35);
    banner.rotation.y = side * 0.08;
    gate.add(banner);
    const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 2.2, 6), goldMat);
    rod.rotation.z = Math.PI / 2;
    rod.position.set(side * 3.9, 5.35, 0.35);
    gate.add(rod);
  }

  /* ---------------- lanterns ---------------- */
  const lanterns = [];
  const lanternDefs = [
    { x: -4.6, y: 6.2, z: -11.5, s: 1.0 },
    { x: 2.4, y: 6.8, z: -13.0, s: 0.82 },
    { x: 7.2, y: 5.4, z: -10.0, s: 0.9 },
    { x: -8.4, y: 4.6, z: -8.5, s: 0.72 },
  ];

  const lanternMat = new THREE.MeshStandardMaterial({
    color: 0xff9f5a, emissive: 0xff7a2e, emissiveIntensity: 2.6,
    roughness: 0.55, metalness: 0.05,
  });
  const lanternPaperMat = new THREE.MeshStandardMaterial({
    color: 0xffd9b0, emissive: 0xffb36a, emissiveIntensity: 1.3,
    roughness: 0.8,
  });

  for (let i = 0; i < lanternDefs.length; i++) {
    const d = lanternDefs[i];
    const pivot = new THREE.Group();
    pivot.position.set(d.x, d.y, d.z);
    backdrop.add(pivot);

    const chain = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 1.4, 4), woodDark);
    chain.position.y = -0.7;
    pivot.add(chain);

    const body = new THREE.Mesh(new THREE.SphereGeometry(0.5, 20, 14), lanternMat);
    body.scale.set(1, 1.28, 1);
    body.position.y = -1.7;
    pivot.add(body);

    for (let r = -1; r <= 1; r++) {
      const rib = new THREE.Mesh(new THREE.TorusGeometry(0.49, 0.018, 4, 24), woodDark);
      rib.rotation.x = Math.PI / 2;
      rib.position.y = -1.7 + r * 0.24;
      rib.scale.set(1, 1, 1.1);
      pivot.add(rib);
    }

    const capTop = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.32, 0.12, 8), woodDark);
    capTop.position.y = -1.08;
    pivot.add(capTop);
    const capBottom = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.22, 0.12, 8), woodDark);
    capBottom.position.y = -2.3;
    pivot.add(capBottom);
    const tassel = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.5, 4), new THREE.MeshBasicMaterial({ color: 0xd8a24e }));
    tassel.position.y = -2.6;
    pivot.add(tassel);

    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: softTex, color: 0xffa25e, transparent: true, opacity: 0.55,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    glow.position.y = -1.7;
    glow.scale.setScalar(4.6 * d.s);
    pivot.add(glow);

    pivot.scale.setScalar(d.s);
    pivot.userData.phase = Math.random() * TAU;
    pivot.userData.baseRot = 0;
    lanterns.push(pivot);

    if (i < 3) {
      const light = new THREE.PointLight(0xff9a58, 42 * d.s, 42, 2);
      light.position.set(d.x, d.y - 1.7 * d.s, d.z + 1.5);
      root.add(light);
    }
  }

  /* ---------------- bamboo ---------------- */
  const bambooMat = new THREE.MeshStandardMaterial({
    color: 0x1d3d2b, roughness: 0.72, metalness: 0.04,
    emissive: 0x050f08, emissiveIntensity: 0.5,
  });
  const bambooLeafMat = new THREE.MeshStandardMaterial({
    color: 0x193b2d, roughness: 0.8, side: THREE.DoubleSide,
    emissive: 0x041007, emissiveIntensity: 0.4,
  });

  const bambooLeafGeo = new THREE.PlaneGeometry(1, 0.25);
  const bambooGroup = new THREE.Group();
  backdrop.add(bambooGroup);

  for (let cluster = 0; cluster < 2; cluster++) {
    const dir = cluster === 0 ? -1 : 1;
    for (let i = 0; i < 7; i++) {
      const x = dir * (5.8 + Math.random() * 4.5);
      const z = -13 + Math.random() * 7;
      const h = 9 + Math.random() * 8;
      const lean = (Math.random() - 0.5) * 0.12;
      const stalk = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.11, h, 6), bambooMat);
      stalk.position.set(x, -8 + h / 2, z);
      stalk.rotation.z = lean;
      bambooGroup.add(stalk);
      for (let n = 0; n < 5; n++) {
        const y = -8 + h * (0.35 + Math.random() * 0.6);
        const leaf = new THREE.Mesh(bambooLeafGeo, bambooLeafMat);
        leaf.position.set(x + dir * rand(0.1, 0.6), y, z + 0.3);
        leaf.rotation.set(rand(-0.4, 0.4), rand(-0.6, 0.6), rand(-0.6, 0.6) + (dir > 0 ? 0 : Math.PI));
        leaf.scale.set(rand(0.8, 1.8), rand(0.8, 1.4), 1);
        bambooGroup.add(leaf);
      }
    }
  }

  /* ---------------- floor mist ---------------- */
  const mists = [];
  for (let i = 0; i < 3; i++) {
    const mat = new THREE.MeshBasicMaterial({
      map: mistTex, transparent: true, opacity: 0.14 - i * 0.03,
      depthWrite: false, blending: THREE.AdditiveBlending, color: i === 0 ? 0x9a7ac4 : 0xd08a7a,
    });
    const mist = new THREE.Mesh(new THREE.PlaneGeometry(34, 7), mat);
    mist.position.set(0, -7.4 + i * 0.6, -10 - i * 4);
    mist.renderOrder = 2;
    backdrop.add(mist);
    mists.push({ mesh: mist, baseX: 0, phase: Math.random() * TAU });
  }

  /* ---------------- petals ---------------- */
  const petalCount = 56;
  const petalMat = new THREE.MeshBasicMaterial({
    color: 0xff9fc0, transparent: true, opacity: 0.72, side: THREE.DoubleSide,
    depthWrite: false,
  });
  const petals = new THREE.InstancedMesh(petalGeometry(), petalMat, petalCount);
  petals.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  petals.frustumCulled = false;
  backdrop.add(petals);

  const petalData = [];
  const dummy = new THREE.Object3D();
  const petalColors = [0xff9fc0, 0xffb7cf, 0xf7a7d7, 0xffc7dc, 0xd9a6ff];
  for (let i = 0; i < petalCount; i++) {
    petalData.push({
      x: rand(-11, 11),
      y: rand(-10, 11),
      z: rand(-10, -1.5),
      rotX: rand(0, TAU),
      rotY: rand(0, TAU),
      rotZ: rand(0, TAU),
      spin: rand(-1.2, 1.2),
      speed: rand(0.25, 0.7),
      phase: rand(0, TAU),
      scale: rand(0.5, 1.25),
    });
    petals.setColorAt(i, new THREE.Color(petalColors[i % petalColors.length]));
  }
  petals.instanceColor.needsUpdate = true;

  /* ---------------- embers / motes ---------------- */
  const emberCount = 110;
  const emberGeo = new THREE.BufferGeometry();
  const emberPos = new Float32Array(emberCount * 3);
  const emberData = [];
  for (let i = 0; i < emberCount; i++) {
    const x = rand(-10, 10);
    const y = rand(-9, 10);
    const z = rand(-12, 1);
    emberPos[i * 3] = x; emberPos[i * 3 + 1] = y; emberPos[i * 3 + 2] = z;
    emberData.push({ x, y, z, speed: rand(0.08, 0.35), phase: rand(0, TAU), amp: rand(0.2, 0.8) });
  }
  emberGeo.setAttribute('position', new THREE.BufferAttribute(emberPos, 3));
  const emberMat = new THREE.PointsMaterial({
    size: 0.14, map: glowTex, color: 0xffc078, transparent: true, opacity: 0.7,
    blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
  });
  const embers = new THREE.Points(emberGeo, emberMat);
  embers.frustumCulled = false;
  backdrop.add(embers);

  /* ---------------- foreground bokeh ---------------- */
  const bokeh = [];
  for (let i = 0; i < 7; i++) {
    const mat = new THREE.SpriteMaterial({
      map: softTex, color: i % 3 === 0 ? 0x8b7cff : 0xffb36a,
      transparent: true, opacity: 0.05 + Math.random() * 0.05,
      blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
    });
    const sprite = new THREE.Sprite(mat);
    sprite.position.set(rand(-10, 10), rand(-7, 7), rand(3, 6));
    sprite.scale.setScalar(rand(2.5, 7));
    sprite.renderOrder = 40;
    root.add(sprite);
    bokeh.push({ sprite, phase: rand(0, TAU), baseY: sprite.position.y, baseX: sprite.position.x });
  }

  /* ---------------- lights ---------------- */
  const hemi = new THREE.HemisphereLight(0x8f9cff, 0x2b0a18, 0.55);
  root.add(hemi);

  const key = new THREE.DirectionalLight(0xffd6a8, 2.7);
  key.position.set(8, 11, 9);
  root.add(key);

  const rim = new THREE.DirectionalLight(0x6fd9ff, 1.9);
  rim.position.set(-9, 4, 6);
  root.add(rim);

  const fill = new THREE.DirectionalLight(0xff7ea8, 0.9);
  fill.position.set(2, -8, 5);
  root.add(fill);

  const accent = new THREE.DirectionalLight(0x9fe8ff, 0.8);
  accent.position.set(0, 0, 8);
  root.add(accent);

  /* ---------------- parallax + animation ---------------- */
  let targetX = 0; let targetY = 0;
  let currentX = 0; let currentY = 0;

  const setParallax = (x, y) => {
    targetX = x;
    targetY = y;
  };

  const update = (dt, time) => {
    currentX += (targetX - currentX) * Math.min(1, dt * 2.5);
    currentY += (targetY - currentY) * Math.min(1, dt * 2.5);
    backdrop.position.x = -currentX * 0.55;
    backdrop.position.y = currentY * 0.32;
    gate.rotation.y = currentX * 0.03;

    moonGlow.material.opacity = 0.46 + Math.sin(time * 0.6) * 0.04;
    moonGlow.scale.setScalar(24 + Math.sin(time * 0.5) * 0.8);
    moonGlow2.material.opacity = 0.12 + Math.sin(time * 0.4 + 1) * 0.02;

    for (const l of lanterns) {
      l.rotation.z = Math.sin(time * 0.55 + l.userData.phase) * 0.055;
      l.rotation.x = Math.cos(time * 0.4 + l.userData.phase) * 0.02;
    }

    for (const c of clouds) {
      c.sprite.position.x = c.baseX + Math.sin(time * c.speed + c.phase) * 8 + time * 0.035;
    }

    for (const m of mists) {
      m.mesh.position.x = Math.sin(time * 0.08 + m.phase) * 2.5;
    }

    // petals
    for (let i = 0; i < petalCount; i++) {
      const p = petalData[i];
      p.y -= p.speed * dt;
      p.x += Math.sin(time * 0.6 + p.phase) * 0.24 * dt;
      p.rotZ += p.spin * dt;
      p.rotY += p.spin * 0.6 * dt;
      if (p.y < -11) {
        p.y = 11 + Math.random() * 3;
        p.x = rand(-11, 11);
      }
      if (p.x < -13) p.x = 13;
      if (p.x > 13) p.x = -13;
      dummy.position.set(p.x, p.y, p.z);
      dummy.rotation.set(p.rotX + Math.sin(time * 0.4 + p.phase) * 0.3, p.rotY, p.rotZ);
      dummy.scale.setScalar(p.scale);
      dummy.updateMatrix();
      petals.setMatrixAt(i, dummy.matrix);
    }
    petals.instanceMatrix.needsUpdate = true;

    // embers
    const ep = emberGeo.attributes.position.array;
    for (let i = 0; i < emberCount; i++) {
      const e = emberData[i];
      e.y += e.speed * dt;
      if (e.y > 11) { e.y = -9; e.x = rand(-10, 10); }
      ep[i * 3] = e.x + Math.sin(time * 0.35 + e.phase) * e.amp * 0.3;
      ep[i * 3 + 1] = e.y;
      ep[i * 3 + 2] = e.z;
    }
    emberGeo.attributes.position.needsUpdate = true;
    emberMat.opacity = 0.55 + Math.sin(time * 1.4) * 0.12;

    for (const b of bokeh) {
      b.sprite.position.y = b.baseY + Math.sin(time * 0.3 + b.phase) * 0.6;
      b.sprite.position.x = b.baseX + Math.cos(time * 0.22 + b.phase) * 0.6;
    }

    if (root.userData.stars) {
      root.userData.stars.material.opacity = 0.78 + Math.sin(time * 1.7) * 0.08;
    }
  };

  const setAccent = (hex) => {
    accent.color.set(hex);
    accent.intensity = 0.7;
  };

  return { root, backdrop, update, setParallax, setAccent, moon, gate, lights: { hemi, key, rim, fill, accent } };
}

function rand(a, b) { return a + Math.random() * (b - a); }

const TIERS = [
  { name: 'TEMPERED BLADE', next: 'CHAIN 5 TO GILD', color: '#8beaff', glow: 'rgba(139,234,255,0.55)' },
  { name: 'GILDED EDGE', next: 'CHAIN 10 TO STORM', color: '#ffd583', glow: 'rgba(255,213,131,0.55)' },
  { name: 'STORMBOUND BLADE', next: 'CHAIN 17 TO MYTH', color: '#ff8bd0', glow: 'rgba(255,139,208,0.55)' },
  { name: 'MYTHIC EDGE', next: 'MAXIMUM RADIANCE', color: '#e8f7ff', glow: 'rgba(232,247,255,0.65)' },
];
export { TIERS };

export class UI {
  constructor(handlers) {
    this.h = handlers;
    this.el = {
      hud: document.getElementById('hud'),
      score: document.getElementById('score'),
      hudBest: document.getElementById('hud-best'),
      chainBadge: document.getElementById('chain-badge'),
      chainRing: document.getElementById('chain-ring'),
      chainValue: document.getElementById('chain-value'),
      chainMult: document.getElementById('chain-mult'),
      lives: document.getElementById('lives'),
      calloutLayer: document.getElementById('callout-layer'),
      bladeStatus: document.getElementById('blade-status'),
      bladeTier: document.getElementById('blade-tier'),
      bladeNext: document.getElementById('blade-next'),
      bladeBar: document.getElementById('blade-bar'),
      tutorial: document.getElementById('tutorial-hint'),
      startScreen: document.getElementById('start-screen'),
      startBest: document.getElementById('start-best'),
      gameover: document.getElementById('gameover-screen'),
      pause: document.getElementById('pause-screen'),
      finalScore: document.getElementById('final-score'),
      statFruit: document.getElementById('stat-fruit'),
      statChain: document.getElementById('stat-chain'),
      statTime: document.getElementById('stat-time'),
      resultBest: document.getElementById('result-best'),
      recordBadge: document.getElementById('record-badge'),
      resultKicker: document.getElementById('result-kicker'),
      resultTitle: document.getElementById('result-title'),
      flash: document.getElementById('flash'),
      hurt: document.getElementById('hurt'),
      muteBtn: document.getElementById('mute-btn'),
      startMute: document.getElementById('start-mute-btn'),
      pauseBtn: document.getElementById('pause-btn'),
    };
    this.hearts = [...this.el.lives.querySelectorAll('.heart')];
    this.lastScore = 0;
    this.heartCount = 3;
    this.tierIndex = -1;

    document.getElementById('play-btn').addEventListener('click', () => this.h('play'));
    document.getElementById('retry-btn').addEventListener('click', () => this.h('retry'));
    document.getElementById('menu-btn').addEventListener('click', () => this.h('menu'));
    document.getElementById('resume-btn').addEventListener('click', () => this.h('resume'));
    document.getElementById('quit-btn').addEventListener('click', () => this.h('quit'));
    document.getElementById('pause-btn').addEventListener('click', () => this.h('pause'));
    document.getElementById('mute-btn').addEventListener('click', () => this.h('mute'));
    document.getElementById('start-mute-btn').addEventListener('click', () => this.h('mute'));
    window.addEventListener('keydown', (e) => {
      if (e.key === 'm' || e.key === 'M') this.h('mute');
    });
  }

  setMuted(muted) {
    document.body.classList.toggle('is-muted', muted);
    if (this.el.muteBtn) this.el.muteBtn.setAttribute('aria-label', muted ? 'Unmute sound' : 'Mute sound');
    if (this.el.startMute) {
      const label = this.el.startMute.querySelector('.mute-label');
      if (label) label.textContent = muted ? 'SOUND OFF' : 'SOUND ON';
    }
  }

  setBest(best) {
    this.el.startBest.textContent = best.toLocaleString();
    this.el.hudBest.textContent = best.toLocaleString();
    this.el.resultBest.textContent = best.toLocaleString();
  }

  setScore(value) {
    if (value === this.lastScore) return;
    this.lastScore = value;
    this.el.score.textContent = value.toLocaleString();
    this.el.score.animate(
      [{ transform: 'scale(1.08)' }, { transform: 'scale(1)' }],
      { duration: 160, easing: 'cubic-bezier(0.2,1.4,0.4,1)' },
    );
  }

  setChain(chain, mult, pct, tier) {
    this.el.chainValue.textContent = chain;
    this.el.chainMult.innerHTML = `&times;${mult.toFixed(1)}`;
    this.el.chainRing.style.setProperty('--p', `${Math.max(0, Math.min(100, pct * 100))}%`);
    if (tier) {
      this.el.chainBadge.style.setProperty('--tier', tier.color);
      this.el.chainBadge.style.setProperty('--tier-soft', tier.glow);
      this.el.chainRing.style.setProperty('--tier', tier.color);
      this.el.chainRing.style.setProperty('--tier-soft', tier.glow);
      this.el.bladeStatus.style.setProperty('--tier', tier.color);
    }
    if (chain > 0) {
      this.el.chainBadge.classList.remove('bump');
      void this.el.chainBadge.offsetWidth;
      this.el.chainBadge.classList.add('bump');
      setTimeout(() => this.el.chainBadge.classList.remove('bump'), 160);
    }
  }

  setTier(index) {
    if (index === this.tierIndex) return;
    const changed = this.tierIndex !== -1;
    this.tierIndex = index;
    const tier = TIERS[index];
    this.el.bladeTier.textContent = tier.name;
    this.el.bladeNext.textContent = tier.next;
    this.el.bladeStatus.classList.toggle('awake', index >= 2);
    if (changed) {
      this.el.chainBadge.classList.remove('tier-up');
      void this.el.chainBadge.offsetWidth;
      this.el.chainBadge.classList.add('tier-up');
    }
  }

  setBladeProgress(pct) {
    this.el.bladeBar.style.width = `${Math.max(0, Math.min(1, pct)) * 100}%`;
  }

  setLives(lives, animateLoss = false) {
    this.hearts.forEach((heart, i) => {
      const lost = i >= lives;
      heart.classList.toggle('lost', lost);
      if (!lost && this.heartCount !== lives) {
        heart.classList.remove('pulse');
        void heart.offsetWidth;
        heart.classList.add('pulse');
      }
    });
    if (animateLoss) {
      const heart = this.hearts[Math.max(0, lives)];
      if (heart) {
        heart.classList.remove('pulse');
        void heart.offsetWidth;
        heart.classList.add('pulse');
      }
    }
    this.el.lives.setAttribute('aria-label', `${lives} ${lives === 1 ? 'life' : 'lives'} remaining`);
    this.heartCount = lives;
  }

  callout(text, kind = '', sub = '') {
    const layer = this.el.calloutLayer;
    layer.querySelectorAll('.callout').forEach((n) => n.remove());
    const node = document.createElement('div');
    node.className = `callout ${kind}`;
    node.textContent = text;
    if (sub) {
      const s = document.createElement('span');
      s.className = 'sub';
      s.textContent = sub;
      node.appendChild(s);
    }
    layer.appendChild(node);
    setTimeout(() => node.remove(), 1200);
  }

  popScore(value) {
    // reserved for floating DOM score accents (in-world popups handle the rest)
  }

  showStart(show) {
    this.el.startScreen.classList.toggle('is-hidden', !show);
  }

  showHUD(show) {
    this.el.hud.classList.toggle('is-hidden', !show);
  }

  showPause(show) {
    this.el.pause.classList.toggle('is-hidden', !show);
  }

  showGameOver(stats) {
    this.el.finalScore.textContent = stats.score.toLocaleString();
    this.el.statFruit.textContent = stats.fruit;
    this.el.statChain.textContent = stats.bestChain;
    this.el.statTime.textContent = stats.time;
    this.el.resultBest.textContent = stats.best.toLocaleString();
    this.el.recordBadge.classList.toggle('is-hidden', !stats.newRecord);
    this.el.resultKicker.textContent = stats.newRecord ? 'A NEW LEGEND' : 'RUN COMPLETE';
    this.el.resultTitle.textContent = stats.newRecord ? 'NIGHT CONQUERED' : 'CHAIN BROKEN';
    this.el.gameover.classList.remove('is-hidden');
  }

  hideGameOver() {
    this.el.gameover.classList.add('is-hidden');
  }

  showHint(show) {
    this.el.tutorial.classList.toggle('hide', !show);
  }

  flash(kind) {
    const el = this.el.flash;
    el.classList.remove('is-bomb', 'is-gold');
    void el.offsetWidth;
    el.classList.add(kind === 'gold' ? 'is-gold' : 'is-bomb');
  }

  hurt() {
    const el = this.el.hurt;
    el.classList.remove('is-hit');
    void el.offsetWidth;
    el.classList.add('is-hit');
  }

  reset() {
    this.lastScore = -1;
    this.setScore(0);
    this.setLives(3);
    this.setChain(0, 1, 0, TIERS[0]);
    this.setTier(0);
    this.setBladeProgress(0);
    this.el.chainValue.textContent = '0';
    this.el.hudBest.textContent = this.el.hudBest.textContent;
  }

  timeString(seconds) {
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  }
}

