  const g = window.__chainblade;
  for (const f of g.fruits) g.scene.remove(f.group);
  g.fruits = [];
  g.effects.trail.clear();
  const list = [
    ['apple', -2.6, 0.2],
    ['orange', -1.0, 0.28],
    ['kiwi', 0.7, 0.24],
    ['dragon', 2.4, 0.3],
  ];
  const out = [];
  for (const [type, x, apex] of list) {
    g.debugSpawn(type, x, apex);
    const f = g.fruits[g.fruits.length - 1];
    const p = f.pos.clone().project(g.camera);
    out.push({ x: (p.x * 0.5 + 0.5) * innerWidth, y: (-p.y * 0.5 + 0.5) * innerHeight, type });
  }
  return out;
});
console.log('PTS', JSON.stringify(pts));
