await page.waitForTimeout(60);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/swipe-end.jpg', type: 'jpeg', quality: 82 });
await page.mouse.up();
await page.waitForTimeout(220);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/swipe-after.jpg', type: 'jpeg', quality: 82 });
console.log('TRAILAFTER', await page.evaluate(() => {
  const g = window.__chainblade;
  return { points: g.effects.trail.points.length, chain: g.chain, score: g.score, sliced: g.fruitSliced, draw: g.effects.trail.outer.geo.drawRange.count, visible: g.effects.trail.outer.mesh.visible };
}));

// Build a big chain quickly
