54:           float hi = smoothstep(0.34, 0.05, length(c - vec2(-0.14, 0.15)));
55:           col += hi * 0.35;
56:           gl_FragColor = vec4(col, a * vAlpha);
57:         }
58:       `,
59:       transparent: true,
60:       depthWrite: false,
61:       depthTest: true,
62:       blending,
63:     });
64: 
65:     this.points = new THREE.Points(this.geometry, this.material);
66:     this.points.frustumCulled = false;
67:     this.points.renderOrder = 20;
68:     scene.add(this.points);
69:   }
70: 
71:   setScale(scale) { this.material.uniforms.uScale.value = scale; }
72: 
73:   spawn({ position, velocity, color, size, life, gravity = 4, drag = 0.15, alpha = 1 }) {
74:     const item = {
75:       px: position.x, py: position.y, pz: position.z,
76:       vx: velocity.x, vy: velocity.y, vz: velocity.z,
77:       color: new THREE.Color(color),
78:       size, life, maxLife: life, gravity, drag, alpha: alpha,
79:     };
80:     if (this.items.length < this.max) {
81:       this.items.push(item);
82:     } else {
83:       this.items[this.cursor % this.max] = item;
84:       this.cursor++;
85:     }
86:   }
87: 
88:   update(dt) {
89:     const items = this.items;
90:     for (let i = items.length - 1; i >= 0; i--) {
91:       const it = items[i];
92:       it.life -= dt;
93:       if (it.life <= 0) {
94:         items.splice(i, 1);
95:         continue;
96:       }
97:       it.vy -= it.gravity * dt;
98:       const dragFactor = Math.exp(-it.drag * dt * 8);
99:       it.vx *= dragFactor;
100:       it.vy *= dragFactor;
101:       it.vz *= dragFactor;
102:       it.px += it.vx * dt;
103:       it.py += it.vy * dt;
104:       it.pz += it.vz * dt;
105:     }
106: 
107:     const n = Math.min(items.length, this.max);
108:     for (let i = 0; i < this.max; i++) {
109:       const it = items[i];
110:       if (!it) {
111:         this.alphas[i] = 0;
112:         this.sizes[i] = 0;
113:         this.positions[i * 3] = 0;
114:         this.positions[i * 3 + 1] = -999;
115:         this.positions[i * 3 + 2] = 0;
116:         continue;
117:       }
118:       const t = it.life / it.maxLife;
119:       this.positions[i * 3] = it.px;
120:       this.positions[i * 3 + 1] = it.py;
121:       this.positions[i * 3 + 2] = it.pz;
122:       this.colors[i * 3] = it.color.r;
123:       this.colors[i * 3 + 1] = it.color.g;
124:       this.colors[i * 3 + 2] = it.color.b;
125:       this.sizes[i] = it.size * (0.55 + t * 0.65);
126:       this.alphas[i] = it.alpha * Math.min(1, t * 2.4);
127:     }
128:     this.geometry.attributes.position.needsUpdate = true;
129:     this.geometry.attributes.aColor.needsUpdate = true;
130:     this.geometry.attributes.aSize.needsUpdate = true;
131:     this.geometry.attributes.aAlpha.needsUpdate = true;
132:     this.geometry.setDrawRange(0, this.max);
133:   }
134: }
