136: /* ------------------------------------------------------------------ */
137: /* ribbon trail                                                        */
138: /* ------------------------------------------------------------------ */
139: class Trail {
140:   constructor(scene, glowTexture) {
141:     this.points = [];
142:     this.maxAge = 0.42;
143:     this.time = 0;
144:     this.color = new THREE.Color(0x8beaff);
145:     this.width = 1;
146:     this.maxPoints = 64;
147: 
148:     const makeRibbon = (opacity, widthFactor, bright) => {
149:       const geo = new THREE.BufferGeometry();
150:       const positions = new Float32Array(this.maxPoints * 2 * 3);
151:       const alphas = new Float32Array(this.maxPoints * 2);
152:       const uvs = new Float32Array(this.maxPoints * 2 * 2);
153:       geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
154:       geo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));
155:       geo.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
156:       const idx = [];
157:       for (let i = 0; i < this.maxPoints - 1; i++) {
158:         idx.push(i * 2, i * 2 + 1, i * 2 + 2, i * 2 + 1, i * 2 + 3, i * 2 + 2);
159:       }
160:       geo.setIndex(idx);
161:       geo.setDrawRange(0, 0);
162:       const mat = new THREE.ShaderMaterial({
163:         uniforms: {
164:           uColor: { value: new THREE.Color(0xffffff) },
165:           uOpacity: { value: opacity },
166:           uBright: { value: bright },
167:         },
168:         vertexShader: `
169:           attribute float aAlpha;
170:           varying float vAlpha;
171:           varying vec2 vUv;
172:           void main() {
173:             vAlpha = aAlpha;
174:             vUv = uv;
175:             gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
176:           }
177:         `,
178:         fragmentShader: `
179:           uniform vec3 uColor;
180:           uniform float uOpacity;
181:           uniform float uBright;
182:           varying float vAlpha;
183:           varying vec2 vUv;
184:           void main() {
185:             float edge = smoothstep(0.0, 0.42, vUv.x) * smoothstep(1.0, 0.58, vUv.x);
186:             float a = vAlpha * edge * uOpacity;
187:             if (a < 0.002) discard;
188:             gl_FragColor = vec4(uColor * uBright, a);
189:           }
190:         `,
191:         transparent: true,
192:         depthWrite: false,
193:         depthTest: false,
194:         blending: THREE.AdditiveBlending,
195:         side: THREE.DoubleSide,
196:       });
197:       const mesh = new THREE.Mesh(geo, mat);
198:       mesh.frustumCulled = false;
199:       mesh.renderOrder = 50;
200:       scene.add(mesh);
201:       return { mesh, geo, positions, alphas, uvs, mat, widthFactor };
202:     };
203: 
204:     this.outer = makeRibbon(0.85, 1.2, 1.65);
205:     this.core = makeRibbon(1.0, 0.44, 3.0);
206: 
207:     this.glow = new THREE.Sprite(new THREE.SpriteMaterial({
208:       map: glowTexture, color: 0x8beaff, transparent: true,
209:       blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
210:     }));
211:     this.glow.scale.setScalar(1.2);
212:     this.glow.renderOrder = 51;
213:     scene.add(this.glow);
214:     this.lastPointAt = -10;
215:   }
216: 
217:   setColor(color) {
218:     const c = new THREE.Color(color);
219:     this.color.copy(c);
220:     this.outer.mat.uniforms.uColor.value.copy(c);
221:     this.core.mat.uniforms.uColor.value.copy(c).lerp(new THREE.Color(0xffffff), 0.65);
222:     this.glow.material.color.copy(c);
223:   }
224: 
225:   push(point, time) {
226:     const pts = this.points;
227:     const last = pts[pts.length - 1];
228:     if (last && Math.hypot(point.x - last.x, point.y - last.y) < 0.008) {
229:       last.t = time;
230:       this.lastPointAt = time;
231:       return;
232:     }
233:     pts.push({ x: point.x, y: point.y, z: point.z ?? 1.4, t: time });
234:     if (pts.length > this.maxPoints) pts.shift();
235:     this.lastPointAt = time;
236:   }
237: 
238:   clear() { this.points.length = 0; }
239: 
240:   update(time) {
241:     this.time = time;
242:     const pts = this.points;
243:     while (pts.length && time - pts[0].t > this.maxAge) pts.shift();
244: 
245:     if (pts.length < 2) {
246:       this.outer.geo.setDrawRange(0, 0);
247:       this.core.geo.setDrawRange(0, 0);
248:       this.glow.material.opacity = 0;
249:       return;
250:     }
251: 
252:     const n = pts.length;
253:     const head = pts[n - 1];
254:     for (const ribbon of [this.outer, this.core]) {
255:       const { positions, alphas, uvs, geo } = ribbon;
256:       const widthBase = 0.26 * ribbon.widthFactor;
257:       for (let i = 0; i < n; i++) {
258:         const p = pts[i];
259:         const prev = pts[Math.max(0, i - 1)];
260:         const next = pts[Math.min(n - 1, i + 1)];
261:         let dx = next.x - prev.x;
262:         let dy = next.y - prev.y;
263:         let len = Math.hypot(dx, dy);
264:         if (len < 0.0001) { dx = 1; dy = 0; len = 1; }
265:         const nx = -dy / len;
266:         const ny = dx / len;
267:         const age = (time - p.t) / this.maxAge;
268:         const u = n === 1 ? 1 : i / (n - 1);
269:         const taper = 0.18 + 0.82 * Math.pow(Math.sin(Math.PI * Math.min(1, u * 1.08)), 0.55);
270:         const width = widthBase * taper * (1 - age * 0.35) * this.width;
271:         const a = Math.pow(Math.max(0, 1 - age), 0.62);
272: 
273:         const i0 = i * 2;
274:         positions[i0 * 3] = p.x + nx * width;
275:         positions[i0 * 3 + 1] = p.y + ny * width;
276:         positions[i0 * 3 + 2] = p.z;
277:         positions[i0 * 3 + 3] = p.x - nx * width;
278:         positions[i0 * 3 + 4] = p.y - ny * width;
279:         positions[i0 * 3 + 5] = p.z;
280:         alphas[i0] = a;
281:         alphas[i0 + 1] = a;
282:         uvs[i0 * 2] = 0; uvs[i0 * 2 + 1] = 0;
283:         uvs[i0 * 2 + 2] = 1; uvs[i0 * 2 + 3] = 0;
284:       }
285:       geo.attributes.position.needsUpdate = true;
286:       geo.attributes.aAlpha.needsUpdate = true;
287:       geo.attributes.uv.needsUpdate = true;
288:       geo.setDrawRange(0, (n - 1) * 6);
289:     }
290: 
291:     this.glow.position.set(head.x, head.y, head.z + 0.05);
292:     const glowAge = (time - head.t) / this.maxAge;
293:     this.glow.material.opacity = Math.max(0, 1 - glowAge) * 0.75;
294:     this.glow.scale.setScalar((0.9 + Math.sin(time * 18) * 0.08) * this.width);
295:   }
296: }
