492:   /* ---------- chain lightning ---------- */
493:   _initArcs() {
494:     this.arcs = [];
495:     for (let i = 0; i < 10; i++) {
496:       const geo = new THREE.BufferGeometry();
497:       const positions = new Float32Array(14 * 3);
498:       geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
499:       const mat = new THREE.LineBasicMaterial({
500:         color: 0x8beaff, transparent: true, opacity: 0,
501:         blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
502:       });
503:       const line = new THREE.Line(geo, mat);
504:       line.visible = false;
505:       line.renderOrder = 49;
506:       line.frustumCulled = false;
507:       this.scene.add(line);
508:       this.arcs.push({ line, geo, mat, age: 0, life: 0.32, active: false });
509:     }
510:   }
511: 
512:   addArc(from, to, color) {
513:     const slot = this.arcs.find((a) => !a.active) || this.arcs[0];
514:     slot.active = true;
515:     slot.age = 0;
516:     slot.life = 0.3;
517:     slot.line.visible = true;
518:     slot.mat.color.set(color);
519:     slot.mat.opacity = 0.95;
520:     const arr = slot.geo.attributes.position.array;
521:     const steps = 14;
522:     const dx = to.x - from.x;
523:     const dy = to.y - from.y;
524:     const len = Math.max(0.001, Math.hypot(dx, dy));
525:     const nx = -dy / len;
526:     const ny = dx / len;
527:     for (let i = 0; i < steps; i++) {
528:       const t = i / (steps - 1);
529:       const jitter = Math.sin(t * Math.PI) * (Math.random() - 0.5) * Math.min(1.6, len * 0.18);
530:       const bow = Math.sin(t * Math.PI) * Math.min(1.3, len * 0.12);
531:       arr[i * 3] = from.x + dx * t + nx * (jitter + bow);
532:       arr[i * 3 + 1] = from.y + dy * t + ny * (jitter + bow);
533:       arr[i * 3 + 2] = 1.5;
534:     }
535:     slot.geo.attributes.position.needsUpdate = true;
536:     slot.geo.setDrawRange(0, steps);
537:     for (let i = 0; i < 6; i++) {
538:       const t = Math.random();
539:       this.sparks.spawn({
540:         position: new THREE.Vector3(from.x + dx * t, from.y + dy * t, 1.5),
541:         velocity: new THREE.Vector3((Math.random() - 0.5) * 1.6, (Math.random() - 0.5) * 1.6, 0),
542:         color: new THREE.Color(color).lerp(new THREE.Color(0xffffff), 0.5),
543:         size: 0.1 + Math.random() * 0.1, life: 0.22 + Math.random() * 0.25,
544:         gravity: 0, drag: 0.2,
545:       });
546:     }
547:   }
548: 
549:   _updateArcs(dt) {
550:     for (const a of this.arcs) {
551:       if (!a.active) continue;
552:       a.age += dt;
553:       const t = a.age / a.life;
554:       if (t >= 1) { a.active = false; a.line.visible = false; continue; }
555:       a.mat.opacity = (1 - t) * 0.9;
556:     }
557:   }
