559:   /* ---------- text popups ---------- */
560:   _initPopups() {
561:     this.popups = [];
562:   }
563: 
564:   _makePopupTexture(text, color, sub) {
565:     const w = 512; const h = 256;
566:     const c = document.createElement('canvas');
567:     c.width = w; c.height = h;
568:     const ctx = c.getContext('2d');
569:     ctx.clearRect(0, 0, w, h);
570:     ctx.textAlign = 'center';
571:     ctx.textBaseline = 'middle';
572:     ctx.font = '800 104px "Trebuchet MS", "Segoe UI", sans-serif';
573:     if (sub) ctx.font = '800 88px "Trebuchet MS", "Segoe UI", sans-serif';
574:     ctx.save();
575:     ctx.shadowColor = 'rgba(0,0,0,0.55)';
576:     ctx.shadowBlur = 18;
577:     ctx.shadowOffsetY = 6;
578:     ctx.lineWidth = 12;
579:     ctx.strokeStyle = 'rgba(24,10,4,0.4)';
580:     ctx.strokeText(text, w / 2, sub ? 92 : h / 2);
581:     ctx.restore();
582:     const grad = ctx.createLinearGradient(0, 30, 0, 190);
583:     grad.addColorStop(0, '#fffdf4');
584:     grad.addColorStop(0.45, color);
