373:       let t = ((f.pos.x - p0.x) * dx + (f.pos.y - p0.y) * dy) / len2;
374:       t = clamp(t, 0, 1);
375:       const cx = p0.x + dx * t;
376:       const cy = p0.y + dy * t;
377:       const dist = Math.hypot(f.pos.x - cx, f.pos.y - cy);
378:       const reach = f.radius * (f.bomb ? 0.92 : 1.0) + 0.04;
379:       if (dist <= reach) {
380:         hits.push({ fruit: f, t, point: new THREE.Vector3(cx, cy, 0) });
381:       }
382:     }
383:     if (!hits.length) return;
384:     hits.sort((a, b) => a.t - b.t);
385: 
386:     const angle = Math.atan2(dy, dx);
387:     for (const hit of hits) {
388:       if (hit.fruit.sliced) continue;
389:       if (hit.fruit.bomb) this._sliceBomb(hit.fruit, hit.point, angle);
390:       else this._sliceFruit(hit.fruit, hit.point, angle, attract);
391:     }
392:     this.fruits = this.fruits.filter((f) => !f.sliced);
393:   }
394: 
395:   _sliceFruit(fruit, hitPoint, angle, attract) {
396:     fruit.sliced = true;
397:     this.scene.remove(fruit.group);
398: 
399:     const halves = this.factory.createHalves(fruit.def.id, fruit.radius, angle);
400:     for (const half of halves) {
401:       half.group.position.copy(fruit.pos);
402:       half.group.position.x += (Math.random() - 0.5) * 0.12;
403:       half.group.position.y += (Math.random() - 0.5) * 0.12;
404:       half.group.position.z += 0.15;
405:       this.scene.add(half.group);
406:       this.debris.push(half);
407:     }
408: 
409:     const tier = TIERS[this._tierIndex()];
410:     this.effects.burstFruit(fruit.pos, fruit.def, fruit.radius, tier.color);
411:     this.effects.addSlash(fruit.pos, angle, tier.color, 0.9 + fruit.radius * 0.3);
412:     if (this.lastSlicePoint) {
413:       this.effects.addArc(this.lastSlicePoint, fruit.pos, tier.color);
414:     }
415:     this.lastSlicePoint = fruit.pos.clone();
416:     this.effects.addShake(0.035 + this._tierIndex() * 0.012);
417: 
418:     if (attract) {
419:       return;
420:     }
421: 
422:     this.fruitSliced++;
423:     this.strokeHits++;
424:     this.lastSliceTime = this.clock;
425:     this.chain++;
426:     this.bestChain = Math.max(this.bestChain, this.chain);
427: 
428:     const prevTier = this.lastTier;
429:     let mult = 1 + Math.min(this.chain, 30) * 0.1;
430:     const isGolden = fruit.def.special;
431:     let gain = Math.round(fruit.def.points * mult);
432: 
433:     let extraChain = 0;
434:     if (isGolden) extraChain = 2;
435:     this.chain += extraChain;
436:     mult = 1 + Math.min(this.chain, 30) * 0.1;
437: 
438:     let heartRestored = false;
439:     if (this.chain > 0 && this.chain % 25 === 0 && this.lives < 3) {
440:       this.lives++;
441:       this.ui.setLives(this.lives);
442:       heartRestored = true;
443:     }
444:     if (isGolden) {
445:       this.effects.flash('gold');
446:       this.audio.frenzy();
447:       if (this.lives < 3) {
448:         this.lives++;
449:         this.ui.setLives(this.lives);
450:         heartRestored = true;
451:       } else {
452:         this.score += 100;
453:         gain += 100;
454:       }
455:       this.effects.addShock(fruit.pos, 0xffd583, 9, 0.8);
456:       this.ui.callout('GOLDEN SURGE', 'frenzy', heartRestored ? 'HEART RESTORED' : 'SCORE SURGE +100');
457:     }
458: 
459:     this.score += gain;
460:     this.ui.setScore(this.score);
461:     this.ui.setChain(this.chain, mult, 1, TIERS[this._tierIndex()]);
462:     const popupPos = fruit.pos.clone();
463:     popupPos.x += (Math.random() - 0.5) * 0.5;
464:     popupPos.y += (Math.random() - 0.5) * 0.25;
465:     this.effects.addPopup(popupPos, `+${gain}`, {
466:       color: isGolden ? '#ffe6a0' : tier.color,
467:       scale: isGolden ? 1.6 : 1.0 + Math.min(this.chain, 12) * 0.018,
468:       sub: isGolden ? 'GOLDEN FRUIT' : '',
469:       life: isGolden ? 1.5 : 1.0,
470:       rise: 2.4,
471:     });
472:     this.audio.slice(this.chain, isGolden);
473: 
474:     const newTier = this._tierIndex();
475:     if (newTier !== this.lastTier) {
476:       this._applyTier(newTier);
477:       this.ui.callout(TIERS[newTier].name, 'chain', 'BLADE TRANSFORMED');
478:       this.audio.chainUp(newTier + 2);
479:     } else if (this.chain > 0 && this.chain % 5 === 0) {
480:       this.audio.chainUp(this.chain / 5);
481:       this.ui.callout(`CHAIN ×${this.chain}`, 'chain', heartRestored ? 'HEART RESTORED' : 'POWER RISING');
482:     }
483: 
484:     if (this.chain === 10) {
485:       this.ui.callout('CHAIN ×10', 'frenzy', 'STORMBOUND AWAKENED');
486:     }
487: 
488:     if (this.strokeHits >= 3) {
489:       const labels = ['', '', '', 'TRIPLE SLICE', 'QUAD SLICE', 'GODLIKE SLICE'];
490:       const label = labels[Math.min(this.strokeHits, 5)];
491:       const bonus = 25 * this.strokeHits;
492:       this.score += bonus;
493:       this.ui.setScore(this.score);
494:       this.ui.callout(label, 'mult', `+${bonus} SWIPE BONUS`);
495:       this.effects.addPopup(new THREE.Vector3(fruit.pos.x, fruit.pos.y + 1.2, 1), `+${bonus}`, {
496:         color: '#8beaff', scale: 1.0, life: 0.9, rise: 1.8,
497:       });
498:     }
499: 
500:     this.ui.setBladeProgress(this._tierProgress());
501:     this.hintTimer = 0;
502:     this.ui.showHint(false);
503:   }
504: 
505:   _sliceBomb(fruit, hitPoint, angle) {
506:     fruit.sliced = true;
507:     this.scene.remove(fruit.group);
508:     this.effects.addSlash(hitPoint, angle, '#ff6a5a', 1.3);
509:     this.effects.burstBomb(fruit.pos);
510:     this.audio.bomb();
511:     this.effects.addShake(0.9);
512:     this.effects.hurtFlash();
513: 
514:     if (this.state !== 'playing') return;
515: 
516:     this.lives = Math.max(0, this.lives - 1);
517:     this.ui.setLives(this.lives, true);
518:     this.ui.callout('BOOM', 'danger', this.chain > 0 ? 'CHAIN LOST · HEART LOST' : 'HEART LOST');
519:     this._resetChain(false);
520:     this.strokeHits = 0;
521:     if (this.lives <= 0) this.gameOver();
522:   }
523: 
524:   _resetChain(showCallout = true) {
525:     if (this.chain <= 0) {
526:       this.chain = 0;
527:       this.ui.setChain(0, 1, 0, TIERS[0]);
528:       this.ui.updateChainTimer(0);
529:       return;
530:     }
531:     const old = this.chain;
532:     this.chain = 0;
533:     this.lastSliceTime = -10;
534:     this.lastSlicePoint = null;
535:     this.ui.setChain(0, 1, 0, TIERS[0]);
536:     this.ui.updateChainTimer(0);
537:     this.ui.setBladeProgress(0);
538:     this._applyTier(0);
539:     this.world.setAccent(TIERS[0].color);
540:     if (showCallout && old >= 3) {
541:       this.ui.callout('CHAIN BROKEN', 'danger', `${old} SLICES FADED`);
542:     }
543:   }
544: 
545:   _tierIndex() {
546:     let idx = 0;
547:     for (let i = 0; i < TIER_THRESHOLDS.length; i++) {
548:       if (this.chain >= TIER_THRESHOLDS[i]) idx = i;
549:     }
550:     return idx;
551:   }
552: 
553:   _tierProgress() {
554:     const idx = this._tierIndex();
555:     if (idx >= TIER_THRESHOLDS.length - 1) return 1;
556:     const lo = TIER_THRESHOLDS[idx];
557:     const hi = TIER_THRESHOLDS[idx + 1];
558:     return clamp((this.chain - lo) / (hi - lo), 0, 1);
559:   }
560: 
561:   _applyTier(index) {
562:     this.lastTier = index;
563:     const tier = TIERS[index];
564:     this.ui.setTier(index);
565:     this.effects.trail.setColor(tier.color);
566:     this.effects.trail.width = 1 + index * 0.16 + Math.min(this.chain, 20) * 0.006;
567:   }
568: 
569:   _currentWindow() {
570:     return Math.max(2.05, 2.7 - Math.min(0.65, this.chain * 0.022));
571:   }
572: 
573:   /* ------------------------------------------------------------------ */
574:   /* spawning                                                            */
575:   /* ------------------------------------------------------------------ */
576:   _spawnOpeners() {
577:     const bottom = this.bounds.bottom;
578:     const specs = [
579:       { type: 'watermelon', x: -this.bounds.halfW * 0.38, apex: 0.66, delay: 0 },
580:       { type: 'orange', x: this.bounds.halfW * 0.3, apex: 0.74, delay: 0.12 },
581:       { type: 'dragon', x: this.bounds.halfW * 0.02, apex: 0.58, delay: 0.28 },
582:     ];
583:     for (const spec of specs) {
584:       this._spawnFruit({ type: spec.type, x: spec.x, bomb: false });
585:       const f = this.fruits[this.fruits.length - 1];
586:       if (!f) continue;
587:       const y = bottom + this.bounds.viewH * 0.3;
588:       f.pos.set(spec.x, y - spec.delay * 6, 0);
589:       f.vel.y = Math.sqrt(2 * GRAVITY * Math.max(2, this.bounds.viewH * spec.apex - y));
590:       f.vel.x = (spec.x > 0 ? -1 : 1) * rand(0.2, 0.6);
591:     }
592:   }
593: 
594:   _chooseType() {
595:     let total = 0;
596:     for (const id of TYPE_LIST) total += FRUIT_DEFS[id].weight;
597:     let roll = Math.random() * total;
598:     for (const id of TYPE_LIST) {
599:       roll -= FRUIT_DEFS[id].weight;
600:       if (roll <= 0) return id;
601:     }
602:     return 'apple';
603:   }
604: 
605:   _scheduleBurst() {
606:     const diff = Math.min(1, this.elapsed / 85);
607:     const roll = Math.random();
608:     let count = 1;
609:     if (roll < 0.04 + 0.08 * diff) count = 4;
610:     else if (roll < 0.15 + 0.14 * diff) count = 3;
611:     else if (roll < 0.42 + 0.13 * diff) count = 2;
612: 
613:     const xs = [];
614:     for (let i = 0; i < count; i++) {
615:       const lane = count === 1 ? rand(-0.65, 0.65) : -0.8 + (1.6 * (i + 0.5)) / count + rand(-0.09, 0.09);
616:       xs.push(lane * this.bounds.halfW);
617:     }
618:     // shuffle lanes so bursts don't sweep left-to-right predictably
619:     for (let i = xs.length - 1; i > 0; i--) {
620:       const j = Math.floor(Math.random() * (i + 1));
621:       [xs[i], xs[j]] = [xs[j], xs[i]];
622:     }
623: 
624:     let bombIndex = -1;
625:     if (this.elapsed > 8) {
626:       const bombChance = 0.07 + 0.1 * diff;
627:       if (Math.random() < bombChance) {
628:         if (count === 1) {
629:           // never a lone bomb; pair it with a fruit
630:           count = 2;
631:           xs.push(rand(-0.7, 0.7) * this.bounds.halfW);
632:           bombIndex = Math.random() < 0.5 ? 0 : 1;
633:         } else {
634:           bombIndex = Math.floor(Math.random() * count);
635:         }
636:       }
637:     }
638: 
639:     for (let i = 0; i < count; i++) {
640:       this.pending.push({
641:         at: this.clock + i * rand(0.06, 0.12),
642:         x: xs[i] ?? rand(-0.7, 0.7) * this.bounds.halfW,
643:         bomb: i === bombIndex,
644:         type: this._chooseType(),
645:       });
646:     }
647: 
648:     if (this.elapsed > 14 && this.clock - this.lastGoldenAt > 23 && Math.random() < 0.09) {
649:       this.lastGoldenAt = this.clock;
650:       this.pending.push({
651:         at: this.clock + 0.15,
652:         x: rand(-0.35, 0.35) * this.bounds.halfW,
653:         bomb: false,
654:         type: 'golden',
655:       });
656:     }
657:   }
658: 
659:   _spawnFruit(spec) {
660:     const scale = this.bounds.scale * (spec.type === 'golden' ? 1.05 : 1);
661:     let created;
662:     if (spec.bomb) created = this.factory.createBomb(this.bounds.scale * 0.98);
663:     else created = this.factory.createFruit(spec.type, scale);
664: 
665:     const bottom = this.bounds.bottom;
666:     const startY = bottom - 1.8;
667:     const apex = bottom + this.bounds.viewH * (spec.bomb ? rand(0.58, 0.84) : rand(0.56, 0.97));
668:     const vy = Math.sqrt(Math.max(1, 2 * GRAVITY * (apex - startY)));
669:     const vx = rand(-0.75, 0.75) + (-spec.x) * 0.035;
670: 
671:     const group = created.group;
672:     group.position.set(spec.x, startY, 0);
673:     group.rotation.set(rand(0, Math.PI * 2), rand(0, Math.PI * 2), rand(0, Math.PI * 2));
674:     this.scene.add(group);
675: 
676:     const fruit = {
677:       group,
678:       pos: group.position,
679:       vel: new THREE.Vector3(vx, vy, 0),
680:       radius: created.radius,
681:       def: created.def,
682:       bomb: !!spec.bomb,
683:       sliced: false,
684:       age: 0,
685:       spin: group.userData.spin || new THREE.Vector3(0, 0, 1),
686:       spinSpeed: group.userData.spinSpeed || 1,
687:       phase: rand(0, Math.PI * 2),
688:       startScale: 0.82,
689:     };
690:     group.scale.setScalar(0.82);
691:     this.fruits.push(fruit);
692:   }
693: 
694:   /* ------------------------------------------------------------------ */
695:   /* attract mode                                                        */
696:   /* ------------------------------------------------------------------ */
697:   _updateAttract(dt) {
698:     this.menuSpawnTimer -= dt;
699:     if (this.menuSpawnTimer <= 0) {
700:       this.menuSpawnTimer = rand(0.95, 1.5);
701:       if (this.fruits.filter((f) => !f.sliced).length < 6) {
702:         const count = Math.random() < 0.28 ? 2 : 1;
703:         for (let i = 0; i < count; i++) {
704:           this._spawnFruit({
705:             x: rand(-0.7, 0.7) * this.bounds.halfW,
706:             bomb: false,
707:             type: this._chooseType(),
708:           });
709:         }
710:       }
711:     }
712: 
713:     if (this.autoSwipe) {
714:       this.autoSwipe.t += dt / this.autoSwipe.duration;
715:       const t = clamp(this.autoSwipe.t, 0, 1);
716:       const ease = t * t * (3 - 2 * t);
717:       const p = new THREE.Vector3().lerpVectors(this.autoSwipe.from, this.autoSwipe.to, ease);
718:       this.effects.trail.push(new THREE.Vector3(p.x, p.y, 1.5), this.clock);
719:       if (this.autoSwipe.t > 0.02) {
720:         this._sampleSwipe(this.autoSwipe.prev, p, true);
721:       }
722:       this.autoSwipe.prev = p;
723:       if (t >= 1) {
724:         this.autoSwipe = null;
725:         this.autoSwipeTimer = rand(1.7, 2.9);
726:       }
727:     } else {
728:       this.autoSwipeTimer -= dt;
729:       if (this.autoSwipeTimer <= 0) {
730:         const candidates = this.fruits.filter((f) => !f.sliced && !f.bomb && f.pos.y > this.bounds.bottom + 3);
731:         if (candidates.length) {
732:           candidates.sort((a, b) => b.pos.y - a.pos.y);
733:           const target = candidates[0];
734:           const side = Math.random() < 0.5 ? -1 : 1;
735:           const from = new THREE.Vector3(
736:             target.pos.x - side * rand(2.4, 3.8),
737:             target.pos.y - rand(1.2, 2.2),
738:             0,
739:           );
740:           const to = new THREE.Vector3(
741:             target.pos.x + side * rand(2.4, 3.8),
742:             target.pos.y + rand(1.2, 2.2),
743:             0,
744:           );
745:           this.autoSwipe = { from, to, prev: from.clone(), t: 0, duration: rand(0.22, 0.3) };
746:           this.effects.trail.clear();
747:         } else {
748:           this.autoSwipeTimer = 0.4;
749:         }
750:       }
751:     }
752:   }
753: 
754:   /* ------------------------------------------------------------------ */
755:   /* update                                                              */
756:   /* ------------------------------------------------------------------ */
757:   update(dt) {
758:     this.ambientClock += dt;
759:     this.world.update(dt, this.ambientClock);
760: 
761:     if (this.state === 'paused') {
762:       // world keeps breathing; gameplay and effects freeze
763:       return;
764:     }
765: 
766:     this.clock += dt;
767: 
768:     if (this.state === 'menu') {
769:       this._updateAttract(dt);
770:     } else if (this.state === 'playing') {
771:       this.elapsed += dt;
772:       this._updateSpawner(dt);
773:       this._updateChain(dt);
774:       this._updateHint(dt);
775:     }
776: 
777:     this._updatePending();
778:     this._updateFruits(dt);
779:     this._updateDebris(dt);
780:     this.effects.update(dt, this.clock);
781:   }
782: 
783:   _updateSpawner(dt) {
784:     const diff = Math.min(1, this.elapsed / 85);
785:     this.spawnTimer -= dt;
786:     if (this.spawnTimer <= 0) {
787:       this._scheduleBurst();
788:       this.spawnTimer = (1.06 - 0.34 * diff) * rand(0.86, 1.18);
789:     }
790:   }
791: 
792:   _updatePending() {
793:     for (let i = this.pending.length - 1; i >= 0; i--) {
794:       if (this.pending[i].at <= this.clock) {
795:         const spec = this.pending[i];
796:         this.pending.splice(i, 1);
797:         if (this.state === 'playing' || this.state === 'menu') this._spawnFruit(spec);
798:       }
799:     }
800:   }
801: 
802:   _updateChain(dt) {
803:     if (this.chain <= 0) return;
804:     const window = this._currentWindow();
805:     const since = this.clock - this.lastSliceTime;
806:     if (since > window) {
807:       this._resetChain(true);
808:       return;
809:     }
810:     this.ui.updateChainTimer(1 - since / window);
811:   }
812: 
813:   _updateHint(dt) {
814:     if (this.hintTimer > 0) {
815:       this.hintTimer -= dt;
816:       if (this.hintTimer <= 0) this.ui.showHint(false);
817:     }
818:   }
819: 
820:   _updateFruits(dt) {
821:     const bottom = this.bounds.bottom;
822:     const half = this.bounds.halfW;
823:     for (let i = this.fruits.length - 1; i >= 0; i--) {
824:       const f = this.fruits[i];
825:       if (f.sliced) continue;
826:       f.age += dt;
827:       f.vel.y -= GRAVITY * dt;
828:       f.pos.x += f.vel.x * dt;
829:       f.pos.y += f.vel.y * dt;
830:       f.pos.z = 0;
831: 
832:       f.group.rotation.x += f.spin.x * f.spinSpeed * dt * 1.9;
833:       f.group.rotation.y += f.spin.y * f.spinSpeed * dt * 1.9;
834:       f.group.rotation.z += f.spin.z * f.spinSpeed * dt * 1.1;
835:       const pop = Math.min(1, f.age / 0.22);
836:       f.group.scale.setScalar(0.82 + pop * 0.18 + Math.sin(this.clock * 2.2 + f.phase) * 0.012);
837: 
838:       if (f.bomb) {
839:         const spark = f.group.userData.spark;
840:         const glow = f.group.userData.glow;
841:         const ring = f.group.userData.ring;
842:         if (spark) spark.scale.setScalar(0.6 + Math.sin(this.clock * 22 + f.phase) * 0.16);
843:         if (glow) glow.material.opacity = 0.4 + Math.sin(this.clock * 18 + f.phase) * 0.16;
844:         if (ring) ring.rotation.z += dt * 2.2;
845:       } else if (f.def?.special) {
846:         const ring = f.group.userData.ring;
847:         const glow = f.group.userData.glow;
848:         if (ring) { ring.rotation.z += dt * 1.5; ring.rotation.y += dt * 0.7; }
849:         if (glow) glow.material.opacity = 0.42 + Math.sin(this.clock * 3 + f.phase) * 0.14;
850:       }
851: 
852:       const out = f.pos.y < bottom - 1.4 && f.vel.y < 0;
853:       const sideways = Math.abs(f.pos.x) > this.bounds.viewW * 0.5 + 2.5;
854:       if (out || sideways) {
855:         this.scene.remove(f.group);
856:         this.fruits.splice(i, 1);
857:         if (!f.bomb && this.state === 'playing') this._onMiss();
858:         continue;
859:       }
860:     }
861:   }
862: 
863:   _onMiss() {
864:     this.lives = Math.max(0, this.lives - 1);
865:     this.ui.setLives(this.lives, true);
866:     this.effects.hurtFlash();
867:     this.effects.addShake(0.12);
868:     this.audio.miss();
869:     const hadChain = this.chain;
870:     this._resetChain(false);
871:     this.ui.callout('MISSED', 'danger', hadChain >= 3 ? `${hadChain} SLICE CHAIN LOST` : 'A HEART FADES');
872:     if (this.lives <= 0) this.gameOver();
873:   }
874: 
875:   _updateDebris(dt) {
876:     const bottom = this.bounds.bottom;
877:     for (let i = this.debris.length - 1; i >= 0; i--) {
878:       const d = this.debris[i];
879:       d.age += dt;
880:       d.velocity.y -= GRAVITY * 0.72 * dt;
881:       d.group.position.x += d.velocity.x * dt;
882:       d.group.position.y += d.velocity.y * dt;
883:       d.group.rotation.x += d.spin.x * dt;
884:       d.group.rotation.y += d.spin.y * dt;
885:       d.group.rotation.z += d.spin.z * dt;
886:       if (d.age > 2.2) {
887:         const k = Math.max(0, 1 - (d.age - 2.2) / 0.5);
888:         d.group.scale.setScalar(k);
889:       }
890:       if (d.age > 2.7 || d.group.position.y < bottom - 4) {
891:         this.scene.remove(d.group);
892:         this.debris.splice(i, 1);
893:       }
