import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
mkdirSync('/home/runner/work/PlayGround/PlayGround/screenshots', { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text().slice(0, 300)); });

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1200);

// 1. auto opener fruit visibility ~1s after clicking play
await page.click('#play-btn');
await page.waitForTimeout(1100);
const opener = await page.evaluate(() => {
  const g = window.__chainblade;
  return {
    state: g.state,
    count: g.fruits.length,
    ys: g.fruits.map(f => +f.pos.y.toFixed(2)),
    hintVisible: !!document.querySelector('#hint')?.classList.contains('show'),
  };
});
console.log('OPENER', JSON.stringify(opener));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/opener.jpg', type: 'jpeg', quality: 80 });

// 2. long swipe with 4 fruits + chain
const pts = await page.evaluate(() => {
  const g = window.__chainblade;
  for (const f of g.fruits) g.scene.remove(f.group);
  g.fruits = []; g.pending = []; g.effects.trail.clear();
  const y = g.bounds.bottom + g.bounds.viewH * 0.5;
  const out = [];
  for (const [type, dx] of [['apple',-3.6],['orange',-1.2],['lemon',1.2],['dragon',3.6]]) {
    g._spawnFruit({ type, x: dx, bomb: false });
    const f = g.fruits[g.fruits.length-1];
    f.pos.set(dx, y, 0); f.vel.set(0, 0, 0);
    const p = f.pos.clone().project(g.camera);
    out.push({x:(p.x*.5+.5)*innerWidth, y:(-p.y*.5+.5)*innerHeight});
  }
  return out;
});
const start = { x: pts[0].x - 150, y: pts[0].y - 90 };
const end = { x: pts[3].x + 150, y: pts[3].y + 90 };
await page.mouse.move(start.x, start.y);
await page.mouse.down();
await page.mouse.move(start.x + (end.x-start.x)*0.35, start.y + (end.y-start.y)*0.35, { steps: 8 });
await page.mouse.move(start.x + (end.x-start.x)*0.7, start.y + (end.y-start.y)*0.7, { steps: 8 });
await page.mouse.move(end.x, end.y, { steps: 8 });
await page.waitForTimeout(50);
console.log('TRAILSTATE', JSON.stringify(await page.evaluate(() => {
  const t = window.__chainblade.effects.trail;
  return { n: t.points.length, draw: t.outer.geo.drawRange.count, chain: window.__chainblade.chain, score: window.__chainblade.score };
})));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/trail2.jpg', type: 'jpeg', quality: 82 });
await page.mouse.up();

// 3. high tier look (chain 16 -> slice makes 17)
await page.evaluate(() => {
  const g = window.__chainblade;
  g.chain = 16;
  g.ui.setChain(16, 1 + 16 * 0.1, 1, g.lastTier >= 0 ? undefined : undefined);
  g._applyTier(g._tierIndex());
  const y = g.bounds.bottom + g.bounds.viewH * 0.5;
  g._spawnFruit({ type: 'golden', x: 0, bomb: false });
  const f = g.fruits[g.fruits.length-1];
  f.pos.set(0, y, 0); f.vel.set(0, 0, 0);
});
await page.waitForTimeout(250);
const gp = await page.evaluate(() => {
  const g = window.__chainblade;
  const f = g.fruits[g.fruits.length-1];
  const p = f.pos.clone().project(g.camera);
  return { x:(p.x*.5+.5)*innerWidth, y:(-p.y*.5+.5)*innerHeight };
});
await page.mouse.move(gp.x - 260, gp.y);
await page.mouse.down();
await page.mouse.move(gp.x, gp.y, { steps: 6 });
await page.waitForTimeout(80);
console.log('TIER', JSON.stringify(await page.evaluate(() => {
  const g = window.__chainblade;
  return { chain: g.chain, tier: g.lastTier, score: g.score, callout: document.querySelector('#callout')?.textContent?.trim().slice(0,60) };
})));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/tier-high2.jpg', type: 'jpeg', quality: 82 });
await page.mouse.up();

// 4. pause + resume
await page.evaluate(() => { window.__chainblade.pause(); });
await page.waitForTimeout(450);
console.log('PAUSE', JSON.stringify(await page.evaluate(() => ({
  state: window.__chainblade.state,
  visible: !!document.querySelector('#pause-screen')?.classList.contains('show'),
}))));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/pause2.jpg', type: 'jpeg', quality: 80 });
await page.evaluate(() => { window.__chainblade.resume(); });
console.log('RESUME', await page.evaluate(() => window.__chainblade.state));

// 5. bomb hit
await page.evaluate(() => {
  const g = window.__chainblade;
  g.lives = 3; g.ui.setLives(3);
  for (const f of g.fruits) g.scene.remove(f.group);
  g.fruits = []; g.pending = [];
  g.chain = 7; g._applyTier(g._tierIndex());
  g._spawnFruit({ type: 'watermelon', x: -2, bomb: false });
  g._spawnFruit({ type: 'bomb', x: 0, bomb: true });
  const y = g.bounds.bottom + g.bounds.viewH * 0.5;
  for (const f of g.fruits) { f.pos.set(f.pos.x, y, 0); f.vel.set(0,0,0); }
});
await page.waitForTimeout(150);
const bp = await page.evaluate(() => {
  const g = window.__chainblade;
  const f = g.fruits[g.fruits.length-1];
  const p = f.pos.clone().project(g.camera);
  return { x:(p.x*.5+.5)*innerWidth, y:(-p.y*.5+.5)*innerHeight };
});
await page.mouse.move(bp.x - 260, bp.y - 40);
await page.mouse.down();
await page.mouse.move(bp.x, bp.y, { steps: 6 });
await page.waitForTimeout(60);
console.log('BOMB', JSON.stringify(await page.evaluate(() => {
  const g = window.__chainblade;
  return { lives: g.lives, chain: g.chain, state: g.state, score: g.score };
})));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/bomb2.jpg', type: 'jpeg', quality: 82 });
await page.mouse.up();

// 6. game over
await page.evaluate(() => {
  const g = window.__chainblade;
  g.lives = 1; g.ui.setLives(1);
  for (const f of g.fruits) g.scene.remove(f.group);
  g.fruits = []; g.pending = [];
  g._spawnFruit({ type: 'bomb', x: 0, bomb: true });
  const y = g.bounds.bottom + g.bounds.viewH * 0.5;
  const f = g.fruits[g.fruits.length-1];
  f.pos.set(0, y, 0); f.vel.set(0,0,0);
});
await page.waitForTimeout(150);
const op = await page.evaluate(() => {
  const g = window.__chainblade;
  const f = g.fruits[g.fruits.length-1];
  const p = f.pos.clone().project(g.camera);
  return { x:(p.x*.5+.5)*innerWidth, y:(-p.y*.5+.5)*innerHeight };
});
await page.mouse.move(op.x - 250, op.y - 30);
await page.mouse.down();
await page.mouse.move(op.x, op.y, { steps: 5 });
await page.mouse.up();
await page.waitForTimeout(1500);
console.log('OVER', JSON.stringify(await page.evaluate(() => ({
  state: window.__chainblade.state,
  visible: !!document.querySelector('#gameover-screen')?.classList.contains('show'),
  title: document.querySelector('#gameover-screen h1, #gameover-screen .go-title')?.textContent?.trim(),
}))));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/over2.jpg', type: 'jpeg', quality: 80 });

// 7. restart via Play Again button
const again = page.locator('#gameover-screen button, #play-again');
console.log('AGAIN buttons', await again.count());
const playAgain = page.locator('#play-again');
if (await playAgain.count()) {
  await playAgain.click();
  await page.waitForTimeout(600);
  console.log('RESTART', JSON.stringify(await page.evaluate(() => ({
    state: window.__chainblade.state, lives: window.__chainblade.lives, score: window.__chainblade.score,
    gameover: !!document.querySelector('#gameover-screen')?.classList.contains('show'),
  }))));
}

// 8. mobile layout
const mob = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
mob.on('pageerror', (e) => errors.push('MOBILE PAGEERROR ' + e.message));
await mob.goto('http://localhost:3002/', { waitUntil: 'load' });
await mob.waitForTimeout(1600);
await mob.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/start-mobile2.jpg', type: 'jpeg', quality: 82 });
await mob.tap('#play-btn');
await mob.waitForTimeout(1400);
const layout = await mob.evaluate(() => {
  const ids = ['hud', 'hud-score', 'chain-widget', 'lives', 'tier-label', 'sword-bar'];
  const vw = innerWidth, vh = innerHeight;
  const out = {};
  for (const id of ids) {
    const el = document.querySelector('#' + id);
    if (!el) { out[id] = null; continue; }
    const r = el.getBoundingClientRect();
    out[id] = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), off: r.x < -1 || r.y < -1 || r.right > vw + 1 || r.bottom > vh + 1 };
  }
  return { vw, vh, out, safeTop: getComputedStyle(document.querySelector('#hud')).paddingTop, canvas: [document.querySelector('canvas').width, document.querySelector('canvas').height] };
});
console.log('MOBILE LAYOUT', JSON.stringify(layout, null, 1));
await mob.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/play-mobile2.jpg', type: 'jpeg', quality: 82 });

// mobile swipe
const mpts = await mob.evaluate(() => {
  const g = window.__chainblade;
  const out = [];
  for (const f of g.fruits) {
    const p = f.pos.clone().project(g.camera);
    out.push({ x: (p.x*.5+.5)*innerWidth, y: (-p.y*.5+.5)*innerHeight });
  }
  return out;
});
if (mpts.length) {
  const s = { x: Math.max(10, mpts[0].x - 60), y: Math.min(innerHeight-10, mpts[0].y + 40) };
  const e = { x: Math.min(380, mpts[0].x + 280), y: Math.max(10, mpts[0].y - 40) };
  await mob.touchscreen.tap(Math.round((s.x+e.x)/2), Math.round((s.y+e.y)/2));
  await mob.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/play-mobile2.jpg', type: 'jpeg', quality: 82 });
}

console.log('ERRORS', errors.length ? JSON.stringify(errors, null, 1) : 'none');
await browser.close();

