import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
mkdirSync('/home/runner/work/PlayGround/PlayGround/screenshots', { recursive: true });
const S = '/home/runner/work/PlayGround/PlayGround/screenshots/';
const browser = await chromium.launch({ ...config.browser.launchOptions });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text().slice(0, 300)); });

const state = () => page.evaluate(() => {
  const g = window.__chainblade;
  return { state: g.state, lives: g.lives, score: g.score, chain: g.chain, tier: g.lastTier, fruits: g.fruits.length };
});

async function pin() {
  await page.evaluate(() => {
    const g = window.__chainblade;
    if (!g.__origUpd) {
      g.__origUpd = g._updateFruits;
      g._updateFruits = function (dt) {
        for (const f of this.fruits) {
          f.age += dt;
          if (f.bomb) {
            const spark = f.group.userData.spark;
            if (spark) spark.scale.setScalar(0.6 + Math.sin(this.clock * 22 + f.phase) * 0.16);
          }
        }
      };
      g.__origSpawn = g._updateSpawner;
      g._updateSpawner = () => {};
      g.pending = [];
    }
  });
}

async function place(specs, worldY = 0) {
  return page.evaluate(({ specs, worldY }) => {
    const g = window.__chainblade;
    for (const f of g.fruits) g.scene.remove(f.group);
    g.fruits = []; g.pending = [];
    const y = g.bounds.bottom + g.bounds.viewH * 0.5 + worldY;
    for (const s of specs) {
      g._spawnFruit({ type: s.type, x: s.x, bomb: s.type === 'bomb' });
      const f = g.fruits[g.fruits.length - 1];
      f.pos.set(s.x, y + (s.dy || 0), 0);
      f.vel.set(0, 0, 0);
      f.startScale = 1;
      f.group.scale.setScalar(1);
    }
    return g.fruits.map((f) => {
      const p = f.pos.clone().project(g.camera);
      return { type: f.def?.id, bomb: f.bomb, x: +((p.x * .5 + .5) * innerWidth).toFixed(1), y: +((-p.y * .5 + .5) * innerHeight).toFixed(1) };
    });
  }, { specs, worldY });
}

function swipe(a, b, steps = 3) {
  return (async () => {
    await page.mouse.move(a.x, a.y);
    await page.mouse.down();
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      await page.mouse.move(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t, { steps: 3 });
    }
    await page.waitForTimeout(60);
  })();
}

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1000);
await page.click('#play-btn');
await page.waitForTimeout(1100);
const opener = await page.evaluate(() => {
  const g = window.__chainblade;
  return { state: g.state, count: g.fruits.length, lives: g.lives, hint: document.querySelector('#hint')?.className };
});
