import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
mkdirSync('/home/runner/work/PlayGround/PlayGround/screenshots', { recursive: true });
const S = '/home/runner/work/PlayGround/PlayGround/screenshots/';
const browser = await chromium.launch({ ...config.browser.launchOptions });
const errors = [];

const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text().slice(0, 300)); });

// auto-start capture
await page.goto('http://localhost:3002/?play=1', { waitUntil: 'load' });
await page.waitForTimeout(1200);
console.log('AUTOSTART', JSON.stringify(await page.evaluate(() => {
  const g = window.__chainblade;
  return { state: g.state, fruits: g.fruits.length, hud: !document.querySelector('#hud').classList.contains('is-hidden'), start: document.querySelector('#start-screen').classList.contains('is-hidden') };
})));
await page.screenshot({ path: S + 'auto.jpg', type: 'jpeg', quality: 80 });

// grace miss should not cost a heart
console.log('GRACE', JSON.stringify(await page.evaluate(() => {
  const g = window.__chainblade;
  const before = { lives: g.lives, score: g.score };
  g._spawnFruit({ type: 'apple', x: 0, bomb: false });
  const f = g.fruits[g.fruits.length - 1];
  f.grace = true;
  f.pos.y = g.bounds.bottom - 3; f.vel.y = -1;
  g._updateFruits(0.016);
  return { before, after: { lives: g.lives, score: g.score, fruits: g.fruits.length } };
})));

// real miss costs a heart and resets chain
console.log('MISS', JSON.stringify(await page.evaluate(() => {
  const g = window.__chainblade;
  g.chain = 6; g._applyTier(g._tierIndex());
  const before = { lives: g.lives, chain: g.chain };
  g._spawnFruit({ type: 'apple', x: 0, bomb: false });
  const f = g.fruits[g.fruits.length - 1];
  f.grace = false;
  f.pos.y = g.bounds.bottom - 3; f.vel.y = -1;
  g._updateFruits(0.016);
  return { before, after: { lives: g.lives, chain: g.chain, state: g.state } };
})));

// force game over then retry
await page.evaluate(() => { const g = window.__chainblade; g.lives = 1; g.gameOver(); });
await page.waitForTimeout(1100);
console.log('OVER OBSERVED', JSON.stringify(await page.evaluate(() => ({
  state: window.__chainblade.state,
  hidden: document.querySelector('#gameover-screen').classList.contains('is-hidden'),
  title: document.querySelector('#result-title').textContent,
}))));
await page.screenshot({ path: S + 'over3.jpg', type: 'jpeg', quality: 80 });
await page.click('#retry-btn');
await page.waitForTimeout(500);
console.log('RETRY', JSON.stringify(await page.evaluate(() => {
  const g = window.__chainblade;
  return { state: g.state, lives: g.lives, score: g.score, chain: g.chain, hidden: document.querySelector('#gameover-screen').classList.contains('is-hidden'), fruits: g.fruits.length };
})));

// pause -> quit to menu
await page.click('#pause-btn');
await page.click('#quit-btn');
await page.waitForTimeout(400);
console.log('QUIT', JSON.stringify(await page.evaluate(() => ({
  state: window.__chainblade.state,
  startHidden: document.querySelector('#start-screen').classList.contains('is-hidden'),
  hudHidden: document.querySelector('#hud').classList.contains('is-hidden'),
}))));

// best persistence
await page.evaluate(() => { const g = window.__chainblade; g.score = 321; g._saveBest(); });
await page.waitForTimeout(100);
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(700);
console.log('BEST PERSIST', JSON.stringify(await page.evaluate(() => ({
  startBest: document.querySelector('#start-best').textContent,
  stored: localStorage.getItem('chainblade.best'),
}))));

// mute persistence
await page.click('#start-mute-btn');
const muted1 = await page.evaluate(() => document.body.classList.contains('is-muted'));
await page.reload({ waitUntil: 'load' });
const muted2 = await page.evaluate(() => document.body.classList.contains('is-muted'));
console.log('MUTE PERSIST', muted1, muted2);
// restore mute
if (muted2) await page.click('#start-mute-btn');

// plays after reload (mute button click was a gesture)
await page.click('#play-btn');
await page.waitForTimeout(900);
console.log('PLAY BTN', JSON.stringify(await page.evaluate(() => ({
  state: window.__chainblade.state, fruits: window.__chainblade.fruits.length, score: window.__chainblade.score,
}))));

// ---------- layouts ----------
async function layoutCheck(name, width, height, mobile = false) {
  const p = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile });
  const errs = [];
  p.on('pageerror', (e) => errs.push(e.message));
  await p.goto('http://localhost:3002/?play=1', { waitUntil: 'load' });
  await p.waitForTimeout(1000);
  const r = await p.evaluate(() => {
    const q = (s) => document.querySelector(s)?.getBoundingClientRect();
    const box = (s) => { const b = q(s); return b ? { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), r: Math.round(b.right), b: Math.round(b.bottom) } : null; };
    const vw = innerWidth, vh = innerHeight;
    const names = { score: '.score-panel', chain: '#chain-badge', lives: '#lives', utility: '.utility', blade: '#blade-status', hint: '#tutorial-hint' };
    const out = {};
    for (const [k, s] of Object.entries(names)) out[k] = box(s);
    const off = Object.entries(out).filter(([, b]) => b && (b.x < -1 || b.y < -1 || b.r > vw + 1 || b.b > vh + 1)).map(([k]) => k);
    const overlaps = [];
    if (out.score && out.chain && out.score.r > out.chain.x) overlaps.push('score/chain');
    if (out.chain && out.lives && out.chain.r > out.lives.x) overlaps.push('chain/lives');
    if (out.utility && out.lives && out.utility.y < out.lives.b - 1) overlaps.push('lives/utility');
    return { vw, vh, out, off, overlaps };
  });
  await p.screenshot({ path: S + 'layout-' + name + '.jpg', type: 'jpeg', quality: 80 });
  console.log('LAYOUT ' + name, JSON.stringify(r));
  if (errs.length) console.log('LAYOUT ERRORS ' + name, errs);
  await p.close();
}
await layoutCheck('mobile', 390, 844, true);
await layoutCheck('landscape', 844, 390, true);
await layoutCheck('tablet', 768, 1024, true);
await layoutCheck('desktop1440', 1440, 900, false);

console.log('ERRORS', errors.length ? JSON.stringify(errors, null, 1) : 'none');
await browser.close();

