import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text().slice(0, 200)); });
await page.goto('http://localhost:3002/?play=1', { waitUntil: 'load' });
await page.waitForTimeout(900);
await page.evaluate(() => {
  const g = window.__chainblade;
  window.__auto = setInterval(() => {
    if (g.state !== 'playing') return;
    const target = g.fruits.find((f) => !f.sliced && !f.bomb);
    if (!target) return;
    g._sampleSwipe({ x: target.pos.x - 2.4, y: target.pos.y - 1.8, z: 0 }, { x: target.pos.x + 2.4, y: target.pos.y + 1.8, z: 0 }, false);
  }, 220);
});
for (let i = 0; i < 8; i++) {
  await page.waitForTimeout(1000);
  const s = await page.evaluate(() => {
    const g = window.__chainblade;
    return { t: +g.elapsed.toFixed(1), state: g.state, score: g.score, chain: g.chain, lives: g.lives, tier: g.lastTier, fruits: g.fruits.length, debris: g.debris.length };
  });
  console.log('T+' + (i + 1), JSON.stringify(s));
  if (s.state === 'over') break;
}
await page.evaluate(() => clearInterval(window.__auto));
const final = await page.evaluate(() => {
  const g = window.__chainblade;
  return { state: g.state, score: g.score, best: g.best, bestChain: g.bestChain, fruit: g.fruitSliced, tier: g.lastTier, lives: g.lives };
});
console.log('FINAL', JSON.stringify(final));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/_smoke.jpg', type: 'jpeg', quality: 80 });
console.log('ERRORS', errors.length ? JSON.stringify(errors) : 'none');
await browser.close();

